-- ===== 본문 재추출 반영 1/5 (parse800.py 생성) =====
-- 러닝헤더가 끼어든 본문/뒤바뀐 본문을 PDF에서 다시 추출한 값으로 교체. id·코스·진도는 그대로.
-- 이 파일 70행 / 전체 338행

UPDATE public.words SET meaning = '가계신용통계는 가계부문에 대한 신용공급 규모를 나타내는 통계이다.', detailed_meaning = '가계신용통계는 가계부문에 대한 신용공급 규모를 나타내는 통계이다. 가계신용은 금융기관뿐 아니라 정부, 판매회사 등 기타기관이 가계에 제공한 대출과 외상구매 관련 신용을 모두 포괄하는 것으로 크게 가계대출과 판매신용으로 구분된다. 현재 가계신용통계는 2002년 말 잔액부터 분기별로 제공되고 있다. 가계신용통계는 우리나라 가계부문의 부채규모 및 변동 등을 파악하는 데 널리 활용되고 있다.', related_words = '{}'::text[] WHERE id = 3;  -- 가계신용통계
UPDATE public.words SET meaning = '가상자산(Virtual Asset)은 분산원장 및 암호화 기술을 바탕으로 민간에 의해 디지털 토큰형태로 발행되어 전자적으로 거래 또는 이전 가능한 자산이다.', detailed_meaning = '가상자산(Virtual Asset)은 분산원장 및 암호화 기술을 바탕으로 민간에 의해 디지털 토큰형태로 발행되어 전자적으로 거래 또는 이전 가능한 자산이다. 「가상자산 이용자 보호 등 에 관한 법률」에서는 “경제적 가치를 지닌 것으로서 전자적으로 거래 또는 이전될 수 있는 전자적 증표와 그에 관한 일체의 권리”로 정의하며, 발행인이 사용처와 용도를 제한한 것, 게임물의 이용을 통해 획득한 결과물, 전자화폐, 전자증권, 전자어음 등은 가상자산에서 제외하고 있다. 가상자산은 전통적인 현금, 예금 등의 화폐와는 구별되는 새로운 형태의 자산으로서 일부에서 투자 및 지급수단으로 활용되고 있으나, 가격 변동성이 크고, 신뢰성과 안정성 측면에서 기존 금융자산과 차이가 있다. 국제자금세탁방지기구(FATF; Financial Action Task Force)는 “디지털 방식으로 거래, 이전될 수 있으며, 지급 또는 투자 목적으로 사용될 수 있는 가치의 디지털 증표(digital representation of value)”로 정의하며 법정통화의 디지털 증표라고 할 수 있는 중앙은행 디지털화폐(CBDC)나 증권 등 기존 금융자산의 디지털 표현 형태는 포함되지 않는다. 한국은행은 가상자산이 금융시스템과 통화정책, 지급결제시스템에 미치는 영향에 대해 지속적으로 연구하고 있으며, 국제기구 등과의 협력을 통해 가상자산 시장의 투명성 및 이용자 보호 강화 등을 위한 정책적 ㄱ기반 마련을 위해 노력하고 있다.', related_words = ARRAY['블록체인','비트코인','중앙은행 디지털화폐(CBDC)']::text[] WHERE id = 7;  -- 가상자산
UPDATE public.words SET meaning = '가상자산공개(ICO; Initial Coin Offering)는 주로 혁신적인 신생기업(startup)이 가상자산(virtual asset) 또는 디지털 토큰(digital token, 일종의', detailed_meaning = '가상자산공개(ICO; Initial Coin Offering)는 주로 혁신적인 신생기업(startup)이 가상자산(virtual asset) 또는 디지털 토큰(digital token, 일종의 투자증명)을 이용하여 자금을 조달하는 크라우드펀딩(crowd funding)의 한 방식이다. 가상자산공개(ICO)에서 새로 발행된 가상자산은 법화(legal tender) 또는 비트코인 등 기존의 가상자산과 교환되어 투자자에게 팔린다. 가상자산공개는 거래소에 상장하려는 기업이 투자자에게 자기 주식을 처음 공개적으로 매도하는 기업공개(IPO; Initial Public Offering)에서 연유되었다고 볼 수 있다. 기업공개(IPO)에 참여한 투자자는 해당 기업의 소유권과 관련하여 주식을 획득한다. 반면 가상자산공개(ICO)에 참여한 투자자는 해당 신생기업의 코인(coins) 또는 토큰을 얻는데, 이는 해당 기업이 제안한 프로젝트가 나중에 성공했을 경우평가될 수 있는 가치(value)로 볼 수 있다. ICO는 이더리움(Ethereum)을 포함한 다양한 분산원장 기반 블록체인 네트워크에서 이뤄지고 있다. 우리나라의 경우 향후 논의를 거쳐 ICO를 포함한 가상자산 전반의 발행 및 유통 관련 사항을 가상자산 관련 법률에서 규제할 것으로 보인다.', related_words = ARRAY['가상자산','블록체인','비트코인','빅데이터']::text[] WHERE id = 8;  -- 가상자산공개(ICO)
UPDATE public.words SET meaning = '간편 송금은 모바일 앱이나 온라인 서비스를 통해 상대방에게 손쉽게 금전적 가치를 이전해 주는 서비스이다.', detailed_meaning = '간편 송금은 모바일 앱이나 온라인 서비스를 통해 상대방에게 손쉽게 금전적 가치를 이전해 주는 서비스이다. 이용이 다소 복잡하고 불편한 공인인증서나 OTP(One Time Password, 일회용 비밀번호) 없이도 비밀번호 또는 지문인식과 같은 생체인증만으로 송금이 가능하기 때문에 사용자가 편리함을 느끼게 된다. 국내에서는 토스, 카카오페이, ㄱ네이버페이 등이 간편 송금 방식을 이용하고 있다.', related_words = ARRAY['NFC 기술']::text[] WHERE id = 11;  -- 간편 송금
UPDATE public.words SET meaning = '다국적 금융기관들에 대한 효과적인 규제·감독을 위하여 다국적 금융기관의 본점이 소재한 국가(home country)의 감독 당국과 동 기관의 지점 또는 자회사가 소재한 진출국 (host', detailed_meaning = '다국적 금융기관들에 대한 효과적인 규제·감독을 위하여 다국적 금융기관의 본점이 소재한 국가(home country)의 감독 당국과 동 기관의 지점 또는 자회사가 소재한 진출국 (host country)의 감독 당국들로 구성된 정보공유 및 감독협력 협의체를 의미한다. 금융기관의 영업활동이 전 세계적으로 이루어지고 있는데 반해 규제·감독이 금융기관의 국적또는 지역기반을 중심으로 이루어지고 있는 한계를 극복하기 위하여 설립되었다.', related_words = '{}'::text[] WHERE id = 12;  -- 감독자협의회(Supervisory College)
UPDATE public.words SET meaning = '외국은행 국내지점의 대차대조표상 자본금계정으로 ① 외국은행 국내지점의 설치 및 영업행위를 위하여 본점이 한국은행 등에 외화자금을 매각하여 해당 지점에 공급한 원화 자금 ② 해당 외국은행 국내지점의', detailed_meaning = '외국은행 국내지점의 대차대조표상 자본금계정으로 ① 외국은행 국내지점의 설치 및 영업행위를 위하여 본점이 한국은행 등에 외화자금을 매각하여 해당 지점에 공급한 원화 자금 ② 해당 외국은행 국내지점의 적립금에서 전입하는 자금 ③ 외국은행 국내지점을 추가 로 설치하기 위하여 이미 국내에 설치된 외국은행 국내지점의 이월이익잉여금에서 전입하는 자금 등이 이에 해당한다. 갑기금은 금융위원회로부터 인정받은 금액에 한하여 지점별로 관리하되 각 외은지점의 갑기금은 30억원 이상이어야 한다(「은행법 시행령」 제26 조, 「은행업 감독규정」 제11조).', related_words = ARRAY['을기금(Capital B)']::text[] WHERE id = 13;  -- 갑기금(Capital A)
UPDATE public.words SET meaning = '개별 금융회사의 부실 방지를 목적으로 하는 미시건전성정책(Microprudential policy) 과 달리 경제전체의 금융안정을 위해 시스템 리스크(systemic risk)를 억제하는 정책을', detailed_meaning = '개별 금융회사의 부실 방지를 목적으로 하는 미시건전성정책(Microprudential policy) 과 달리 경제전체의 금융안정을 위해 시스템 리스크(systemic risk)를 억제하는 정책을 의 미한다. 구체적으로 거시건전성정책(Macroprudential policy)의 목표는 시스템 리스크에 대한 선제적 대응, 과도한 금융불균형 축적 억제, 급격한 되돌림 현상(unwinding) 완화, 금융시스템의 복원력(resilience) 강화, 금융연계성 제어 등을 통해 금융위기의 발생가능성과 실물경제에 미치는 부정적인 영향(spillover effects)을 최소화하는 데 있다. 거시건전성정책은 통화정책과 재정정책 등 여러 다른 정책과 긴밀히 관련되어 있으므로, 거시건전성정책의 수립과 집행에는 여러 정책당국 간 정보공유와 협력 및 조정이 긴요하다.', related_words = '{}'::text[] WHERE id = 15;  -- 거시건전성 정책
UPDATE public.words SET meaning = '금융기관의 특정 차주 등에 대한 신용공여가 과도한 경우 해당 거래상대방의 채무불이행등의 발생시 해당 금융기관의 자본건전성을 심하게 훼손할 가능성(편중리스크)이 있다.', detailed_meaning = '금융기관의 특정 차주 등에 대한 신용공여가 과도한 경우 해당 거래상대방의 채무불이행등의 발생시 해당 금융기관의 자본건전성을 심하게 훼손할 가능성(편중리스크)이 있다. 바젤Ⅱ에서는 이러한 편중리스크를 직접 규율하지 않고 각국 감독당국이 편중리스크를 점검·관리하도록 하였다. 우리나라는 은행법 등에서 동일인·동일차주 신용공여 한도 제도를 통해 편중리스크를 관리하고 있다. 한편 금융위기 이후 금융기관간 상호연계성에 의 한 시스템 리스크를 억제하고 편중리스크의 근본적인 관리 필요성이 대두됨에 따라 바젤위원회(BCBS)는 거액익스포저 규제를 2019년 1월 도입하였고 우리나라는 2019년 3월시범실시한 이후 2024년 2월부터 시행 중이다. 동 규제는 거액익스포저를 단일 거래상대방 또는 연계된 거래상대방그룹(경제적 상호의존성이 있는 거래상대방들로 구성되어 거래상대방들 중 하나가 파산하면 다른 모든 거래상대방들이 파산할 가능성이 상당히 높은 ㄱ 그룹)에 대한 익스포저의 합계가 은행 기본자본의 10% 이상인 경우로 정의하고, 거액익스포저 현황을 금융당국에 정기적으로 보고하도록 하는 한편, 거액익스포저비율(거액익스포저를 은행 기본자본으로 나눈 값)이 25%를 초과하지 못하도록 하고 있다.', related_words = ARRAY['동일인 신용공여한도제(동일인 여신한도제)','익스포저']::text[] WHERE id = 16;  -- 거액익스포저 규제
UPDATE public.words SET meaning = '참가기관 간에 주로 거액의 자기자금 또는 고객자금 이체를 위한 지급지시가 이루어지는 시스템을 말한다.', detailed_meaning = '참가기관 간에 주로 거액의 자기자금 또는 고객자금 이체를 위한 지급지시가 이루어지는 시스템을 말한다. 거래 가능한 최소금액이 설정된 것은 아니나 일반적으로 금융시장에서 이루어진 금융기관간 콜거래, 증권 또는 외환매매 등 거액거래에 따른 대금이체지시를 다루기 때문에 건당 이체지시 금액이 상대적으로 크다. 또한 한 나라의 금융기관간 자금거래 대부분이 처리되는 중요시스템으로서 결제시점과 결제리스크 관리의 필요 성이 높아 주요국의 거액지급시스템은 대부분 신용리스크를 제거할 수 있는 실시간총액결제방식을 채택하고 있으며 대부분 중앙은행이 직접 운영한다. 우리나라의 한은금융망 (BOK-Wire+), 미국 연준의 Fedwire, 유럽중앙은행(ECB)의 TARGET2 등이 여기에 해당된다.', related_words = ARRAY['소액지급시스템','지급결제시스템','총액결제시스템']::text[] WHERE id = 17;  -- 거액지급시스템
UPDATE public.words SET meaning = '지급결제시스템을 통해 이루어진 참가기관의 지급지시가 결제된 이후에는 어떠한 상황 ㄱ이나 법률에 의해서도 취소되거나 무효화되지 않고 해당 지급결제시스템의 운영 규칙에 따라 무조건적으로 종결되는 것을', detailed_meaning = '지급결제시스템을 통해 이루어진 참가기관의 지급지시가 결제된 이후에는 어떠한 상황 ㄱ이나 법률에 의해서도 취소되거나 무효화되지 않고 해당 지급결제시스템의 운영 규칙에 따라 무조건적으로 종결되는 것을 의미한다. 결제완결성(Settlement Finality)이 보장되지 않을 경우 지급결제시스템을 통해 종결된 금융기관의 지급지시가 사후적으로 무효화될 수 있어 금융시스템에 큰 혼란을 초래할 수 있다. 「지급 및 시장인프라 위원회」 (CPMI)와 「국제증권감독기구」(IOSCO)가 제정한 국제기준인 「금융시장인프라에 관한 원칙」(PFMI)에서도 결제완결성 원칙이 규정되어 있어 각국 정책당국이 준수하도록 하고 있다. 우리나라는 2006년 4월 시행된 「채무자회생 및 파산에 관한 법률」에서 지급결제시스템에 대한 결제완결성 보장 제도가 도입되었다. 동 법에 따라 한국은행 총재는 금융위원회 위원장과 협의하여 결제완결성이 보장되는 지급결제시스템을 지정할 수 있으며, 지정된 지급결제시스템을 통해 결제된 지급행위는 참가기관의 파산 등의 사유로 취소할수 없도록 하고 있다.', related_words = '{}'::text[] WHERE id = 20;  -- 결제완결성
UPDATE public.words SET meaning = '경기순응성이란 통상 경제주체의 위험인식 및 행위, 금융의 제도 및 규제 등의 효과가 경기변동의 움직임과 같은 방향으로 움직이는 것을 의미한다.', detailed_meaning = '경기순응성이란 통상 경제주체의 위험인식 및 행위, 금융의 제도 및 규제 등의 효과가 경기변동의 움직임과 같은 방향으로 움직이는 것을 의미한다. 예를 들어 은행대출의 경우호경기에는 미래에 대한 낙관적 기대 등으로 여신심사기준도 완화되어 더 크게 증가하여 경기확장에 기여한다. 반면 불경기에는 심사기준이 강화되어 대출이 큰 폭으로 감소하여 불황을 더욱 부추기게 된다. 이러한 은행대출의 경기순응적 행태는 신용팽창 또는 ㄱ위축을 가속시킴으로서 경기변동의 진폭을 더욱 크게 한다. 따라서 정책당국은 정책을 마련할 경우 경기순응성을 완화할 수 있는 경기대응적 정책수단을 개발하기 위해 노력하고 있다.', related_words = ARRAY['거시건전성 정책']::text[] WHERE id = 23;  -- 경기순응성
UPDATE public.words SET meaning = '경기조절정책(Business Adjustment Policy) 또는 경제안정화정책(Stabilization Policy) 은 경기가 지나친 확장 또는 수축 현상을 보일 경우 이를 정상 수준으로', detailed_meaning = '경기조절정책(Business Adjustment Policy) 또는 경제안정화정책(Stabilization Policy) 은 경기가 지나친 확장 또는 수축 현상을 보일 경우 이를 정상 수준으로 되돌리기 위해 정책당국이 취하는 제반 조치를 말한다. 이는 정책당국이 경제 전체의 총수요 수준을 변동시킴으로써 경기 수위를 조절하는 데 초점을 맞추고 있다. 실제 운영에 있어서는 정부지출과 세율을 조정하는 재정정책이 이용되거나 통화량과 금리 수준을 조절하는 통화정책이 활용된다. 즉 경기가 정상 수준을 큰 폭 밑도는 불황에 직면하게 될 경우 정부는 재정지출을 늘리거나 조세를 줄이는 재정정책 수단을 동원한다. 한편 중앙은행은 통화량을 늘리거나 금리를 내리는 정책수단을 활용한다. 이와는 반대로 경기가 지나치게 과열될 경우정책당국은 재정측면에서는 정부지출을 줄이거나 조세를 늘리고, 통화측면에서는 통화량을 줄이거나 금리를 올리는 조치를 취한다.', related_words = ARRAY['재정정책','통화정책']::text[] WHERE id = 24;  -- 경기조절정책/경제안정화정책
UPDATE public.words SET meaning = '경영실태평가는 금융감독당국이 임점 검사 시 금융기관의 경영실태 전반을 점검·평가 하기 위한 제도로, 각 금융기관의 경영실적, 경영의 건전성, 경영진의 경영능력, 법규준수 상황 및 리스크 관리실태', detailed_meaning = '경영실태평가는 금융감독당국이 임점 검사 시 금융기관의 경영실태 전반을 점검·평가 하기 위한 제도로, 각 금융기관의 경영실적, 경영의 건전성, 경영진의 경영능력, 법규준수 상황 및 리스크 관리실태 등 다양한 평가부문을 종합적이고 통일적인 방식에 따라 일정한 등급으로 평가하여 금융기관의 경영상태를 체계적이고 객관적으로 확인하는 방법의 하나이다. 아울러 평가 결과에 따라 부실금융기관에 대해 적기시정조치를 취하는 한 편 감독상 주의 및 관심을 더욱 집중하여 금융기관 경영의 건전성 확보와 금융소비자 보호 등 감독·검사 업무의 효율성을 높일 수 있다. 우리나라는 1996년 10월 은행에 도입한 이후 다른 금융기관에 확대 적용하였다. 경영실태평가의 평가절차나 방식 등은 금융기관별로 거의 동일하나, 금융기관 그룹별 특성에 따라 평가부문과 항목에 차이가 있다. 은행의 경우 해당 은행의 특성(일반은행, 외은지점, 특수은행 등)에 따라 CAMEL-IR방식, ROCA 방식, CACREL 방식을 운용하고 있다. 경영실태평가의 부문별 평가등급 및종합등급은 1등급(우수), 2등급(양호), 3등급(보통), 4등급(취약), 5등급(위험)의 5단계로 구분되며, 일반은행의 경우 각 등급을 3단계(+, 0, -)로 세분화하여 5등급, 15단계로 운용 ㄱ하고 있다.', related_words = ARRAY['CAMEL-IR 방식/ROCA 방식/CACREL 방식']::text[] WHERE id = 27;  -- 경영실태평가/은행경영실태 평가등급제도
UPDATE public.words SET meaning = '경제심리지수란 한국은행이 기업가 또는 소비자들의 경제에 대한 인식을 조사하여 작성한 지표이며, 대표적으로 조사대상을 기업가로 하는 기업경기실사지수(BSI; Business Survey', detailed_meaning = '경제심리지수란 한국은행이 기업가 또는 소비자들의 경제에 대한 인식을 조사하여 작성한 지표이며, 대표적으로 조사대상을 기업가로 하는 기업경기실사지수(BSI; Business Survey Index)와 소비자로 하는 소비자동향지수(CSI; Consumer Survey Index)가 있다. 또한 한 국은행은 BSI와 CSI를 합성하여 민간의 경제상황에 대한 인식을 종합적으로 평가할 수 있는 경제심리지수(ESI; Economic Sentiment Index)도 작성·발표하고 있다. ESI는 BSI와 CSI 중 경기연관성이 높은 항목을 선정하여 이들의 표준화지수를 가중평균하는 등의 과정을 거쳐 산출한다. ESI가 100을 넘으면 현재 민간의 경제심리가 과거 평균보다 낙관적임 을, 100 미만이면 과거 평균보다 비관적임을 각각 나타낸다. 이러한 심리지표들은 실물지표와 대체로 높은 상관관계를 보이지만 때로는 미래정보 및 기대수준의 반영 여부, 질적 통계와 양적 통계 간의 조사척도 차이 등에 따라 다소 괴리되는 움직임을 보이기도 한다.', related_words = ARRAY['기업경기실사지수(BSI)','소비자동향지수(CSI)']::text[] WHERE id = 30;  -- 경제심리지수
UPDATE public.words SET meaning = '다양한 경제지표와 세계 경제 동향 등을 바탕으로 향후 경제 상황이 어떻게 전개될지를 분석하고 예측한 보고서를 말한다.', detailed_meaning = '다양한 경제지표와 세계 경제 동향 등을 바탕으로 향후 경제 상황이 어떻게 전개될지를 분석하고 예측한 보고서를 말한다. 경제전망에는 보통 한 나라의 경제가 얼마나 성장할지 예측하는 경제성장률 전망, 물가가 얼마나 오를지 분석하는 인플레이션 전망, 일자리사정을 예측하는 고용 전망, 외환시장 변동성 및 환율을 살펴보는 환율 전망, 수출입 추세와 무역수지를 예측하는 경상수지 전망 등이 포함된다. 경제주체들이 어떤 경제행위를 결정할 때 경기판단과 예측의 정확성 여부에 따라 미래의 경제적 성과가 크게 달라질 수 있으므로 경제전망은 중요하다. 가계는 경제전망에 따라 재화·서비스, 주택, 주식 등의 구입 시기를 결정한다. 기업은 제품에 대한 수요 전망을 통해 생산량과 시설 투자 계획을 수립한다. 중앙은행은 경기 및 물가 전망을 바탕으로 경제성장과 물가안정을 이루기 위해통화량 및 금리 운용계획을 결정하며, 정부 또한 경제전망에 기초하여 예산 편성, 재정지출 등을 확정한다. 한국은행, IMF, OECD, 각종 민간경제연구소 등 국내외 여러 기관은 정기적으로 경제전망을 발표하고 있다. ㄱ', related_words = ARRAY['경제성장률','인플레이션','경상수지','경기']::text[] WHERE id = 31;  -- 경제전망보고서
UPDATE public.words SET meaning = '소비자물가지수를 구성하는 품목들은 가격이 경직적으로 움직이는 품목과 신축적으로 움 직이는 품목으로 나누어 볼 수 있는데, 그중 경직적으로 움직이는 품목들을 대상으로 만든물가지수를 경직적 물가지수,', detailed_meaning = '소비자물가지수를 구성하는 품목들은 가격이 경직적으로 움직이는 품목과 신축적으로 움 직이는 품목으로 나누어 볼 수 있는데, 그중 경직적으로 움직이는 품목들을 대상으로 만든물가지수를 경직적 물가지수, 신축적으로 움직이는 품목을 대상으로 한 물가지수를 신축적 물가지수라고 한다. 정부의 직·간접적인 영향을 크게 받는 공공서비스, 전기·수도, 담배, 보육·급식 가격이나 개인서비스 요금 등은 대체로 가격이 쉽게 오르거나 내리지 않는 ㄱ 특징을 보이므로 경직적 물가를 구성하는 주요 품목이다. 이러한 경직적 물가의 변동은 장기적인 인플레이션 흐름을 잘 반영하므로 향후 물가 기조를 예측하는데 유용한 지표이다.', related_words = ARRAY['근원인플레이션율']::text[] WHERE id = 35;  -- 경직적 물가지수
UPDATE public.words SET meaning = '고객확인절차(KYC; Know Your Customer)는 테러자금조달 및 자금세탁 등 불법거래차단을 위해 관계당국이 부여한 의무에 따라 고객의 신원을 식별하고 확인하는(verify) 업무절차를', detailed_meaning = '고객확인절차(KYC; Know Your Customer)는 테러자금조달 및 자금세탁 등 불법거래차단을 위해 관계당국이 부여한 의무에 따라 고객의 신원을 식별하고 확인하는(verify) 업무절차를 뜻한다.', related_words = ARRAY['가상통화','비트코인']::text[] WHERE id = 38;  -- 고객확인절차(KYC)
UPDATE public.words SET meaning = '국제노동기구(ILO)에서는 노동 공급과 수요가 일치하지 않아서 일하고 싶은 욕구가 있음 ㄱ에도 불구하고 일을 하고 있지 못하는 노동력의 크기를 나타내는 고용보조지표를 새로이 확정(2013월', detailed_meaning = '국제노동기구(ILO)에서는 노동 공급과 수요가 일치하지 않아서 일하고 싶은 욕구가 있음 ㄱ에도 불구하고 일을 하고 있지 못하는 노동력의 크기를 나타내는 고용보조지표를 새로이 확정(2013월 10월)한 바 있다. 우리나라 통계청에서도 기존의 공식 실업률만으로는 노동시장을 제대로 반영하는데 한계가 있다고 판단하여 2014년 11월부터 새로운 고용보조지표를 발표하고 있다. 고용보조지표는 실업률을 추계하기 위한 공식적인 실업자 이외에 아르바이트 등 단기근로를 하지만 재취업을 원하는 사람(시간관련 추가취업 가능자), 최근구직활동을 안했을 뿐 취업의사가 있고 취업 가능성이 있는 사람(잠재구직자), 그리고 구직노력을 했으나 육아 등으로 당장 일을 시작하지 못하는 사람(잠재취업가능자) 등을 포함 한다. 여기서 비경제활동인구에 포함된 잠재 취업가능자와 잠재 구직자를 합하여 잠재경제활동인구라고 하고, 이를 기존의 경제활동인구와 합산하여 확장경제활동인구라 한다. 현재 고용보조지표는 그 포괄범위에 따라 세 가지 형태로 작성하여 공표되고 있다. 고용보조지표1은 경제활동인구 대비 기존의 취업자 중 시간관련 추가 취업가능자와 실업자의 비율이며, 고용보조지표2는 실업자와 잠재경제활동인구의 합을 확장경제활동인구로 나누어구한다. 한편 고용보조지표3은 확장경제활동인구 대비 시간관련 추가취업 가능자, 실업자및 잠재경제활동인구를 더한 수치의 비율이다. 최근 발표되고 있는 고용보조지표를 보면기존의 공식 실업률과 상당한 차이를 보이고 있는데, 이는 단시간 근로자가 많거나 취업을 희망하고 있지만 구직활동을 하지 않은 사람 등이 그만큼 많다는 것을 의미한다.', related_words = ARRAY['실업률','잠재경제활동인구']::text[] WHERE id = 40;  -- 고용보조지표
UPDATE public.words SET meaning = '고정금리부채권(Straight Bond)이란 정해진 기일에 고정된 이자를 지급하고 정해진 만기에 원금을 지급하는 가장 일반적인 형태의 채권으로 전환사채(CB; Convertible Bond)의', detailed_meaning = '고정금리부채권(Straight Bond)이란 정해진 기일에 고정된 이자를 지급하고 정해진 만기에 원금을 지급하는 가장 일반적인 형태의 채권으로 전환사채(CB; Convertible Bond)의 주식전환권과 같이 특별한 조건이 없는 채권을 말한다. 회사채, 국채 등 대부분의 채권이 고정금리부로 발행된다. 이에 대비되는 채권으로 변동금리부채권(FRN; Floating Rate Note)이 있다. 이는 정해진 기일에 특정 금리(예: 국내에서는 3개월 CD금리, 해외에서는 ㄱ무위험지표금리(RFR; Risk-Free Rate))에 연동된 금리를 지급하고 정해진 만기에 원금을 지급하는 채권이다. 고정금리부채권에 대한 투자는 향후 금리 하락이 예상될 때 유리하며 금리 상승이 예상될 때에는 변동금리부채권에 투자하는 것이 유리하다. 한편 인플레이션이 심할 때 인플레이션을 헤지하기 위한 목적으로 발행되는 채권이 물가연동채권인데 이 는 원금과 이자가 물가상승률(주로 CPI 사용)에 연동하여 증가한다는 면에서 변동금리부채권과 구별된다.', related_words = ARRAY['변동금리부채권(FRN)']::text[] WHERE id = 42;  -- 고정금리부채권(SB)
UPDATE public.words SET meaning = '은행은 보유하고 있는 여신을 자산건전성에 따라 5단계로 분류하여 관리하고 있다.', detailed_meaning = '은행은 보유하고 있는 여신을 자산건전성에 따라 5단계로 분류하여 관리하고 있다. 즉 자산건전성이 가장 양호한 상태인 “정상”에서부터 회수가 어려운 정도에 따라 단계적으로 “요주의”, “고정”, “회수의문”, “추정손실”로 분류한다. 이중 고정, 회수의문, 및 추정손실로 분류된 여신의 합계액을 총여신으로 나눈 비율을 고정이하여신비율이라고 한다. 「은행업감독규정」별표 3에서는 분류단계별 정의를 규정하고 있는데, “고정”은 차주 채무상환능력의 저하를 초래할 수 있는 요인이 현재화되어 채권회수에 상당한 위험이 발생한 여신또는 3개월 이상 연체하거나 부도가 발생한 차주의 여신 중 담보처분에 의한 회수예상가 액 해당부분을 말한다. “회수의문”은 차주 채무상환능력이 현저히 악화되어 채권회수에 심각한 위험이 발생한 여신 및 3개월 이상 12개월 미만의 연체대출채권 보유 차주의 여신 등의 회수예상가액 초과부분을 말한다. “추정손실”은 차주 채무상환능력의 심각한 악화로 회수불능이 확실하여 손실처리가 불가피한 여신 및 12개월 이상 연체대출채권 보유차주의 여신 등의 회수예상가액 초과부분을 말한다.', related_words = ARRAY['자산건전성 분류']::text[] WHERE id = 43;  -- 고정이하여신비율
UPDATE public.words SET meaning = '환율제도는 고정환율제도(Fixed Exchange Rate System)와 자유변동환율제도(Free Floating Exchange Rate System)를 양극단으로 하여 이를 절충하는 다양한', detailed_meaning = '환율제도는 고정환율제도(Fixed Exchange Rate System)와 자유변동환율제도(Free Floating Exchange Rate System)를 양극단으로 하여 이를 절충하는 다양한 형태로 분류될 수 있다. 고정환율제도는 환율을 정부나 중앙은행이 적정하다고 판단하는 수준으로 일정하게 유지하는 제도이다. 반면 자유변동환율제도는 환율이 외환의 수요와 공급에 의 해 자율적으로 결정되도록 하는 환율제도를 말한다. 고정환율제도는 환율 변동에 따른 충격을 완화하고 거시경제정책의 자율성을 어느 정도 확보할 수 있다는 장점이 있으나 이 를 위해서는 자본이동의 제약이 불가피하여 결과적으로 외화유동성이 부족해질 가능성이 있다. 이 경우 대외불균형이 지속되거나 기초경제여건이 악화되면 환투기공격에 쉽게노출되는 단점이 있다. 반면 자유변동환율제도에서는 자본이동이 자유롭게 이루어지므로 외화유동성 확보가 용이하고 외부충격이 환율 변동에 의해 흡수됨으로써 거시경제정책의 자율적 수행이 수월한 장점이 있다. 다만 외환시장 규모가 작고 외부충격의 흡수 능력 ㄱ이 부족한 신흥국은 환율 변동성의 확대가 경제의 교란 요인으로 작용할 가능성이 크다. 한편 어떤 환율제도를 채택하더라도 ① 통화정책의 자율성 ② 자유로운 자본이동 ③ 환율 안정 등 세 가지 정책목표를 동시에 달성하기는 현실적으로 어려운데, 이를 삼불원칙 (impossible trinity 또는 trilemma)이라고 한다.', related_words = ARRAY['삼불원칙','외환시장']::text[] WHERE id = 45;  -- 고정환율제도/자유변동환율제도
UPDATE public.words SET meaning = '소비자물가상승률과 실업률을 더한 값으로 1975년 미국의 경제학자 오쿤(A. Okun)이 국민의 삶에 실업률과 물가상승률이 큰 영향을 준다는 점에 착안하여 만든 국민의 삶의 질을 측정하기 위한', detailed_meaning = '소비자물가상승률과 실업률을 더한 값으로 1975년 미국의 경제학자 오쿤(A. Okun)이 국민의 삶에 실업률과 물가상승률이 큰 영향을 준다는 점에 착안하여 만든 국민의 삶의 질을 측정하기 위한 지표이다. 이 수치가 높을수록 실업자는 늘고 물가는 높아져 한 나 라의 국민이 느끼는 삶의 고통이 늘어남을 의미한다. 그러나 고통지수(Misery Index)를 절대적인 것으로 생각해 나라 간에 단순 비교하기는 어려운 측면이 있는데 이는 나라별로 소비자물가상승률과 실업률을 계산하는 기준이 다르고 빈부격차나 조사대상에 따라서도 느끼는 고통의 정도가 상이할 수 있기 때문이다. 한편 고통지수가 발표된 이후 이를 보완한 다양한 지표들이 개발되고 있는데, 1999년 미국 하버드대 배로(R. Barro)교수는 오쿤의 고통지수에 국민소득증가율과 이자율을 감안한 ‘배로고통지수’(BMI; Barro Misery Index)를 발표한 바 있다.', related_words = ARRAY['소비자물가지수(CPI)','실업률']::text[] WHERE id = 46;  -- 고통지수
UPDATE public.words SET meaning = '공공재는 모든 개인이 공동으로 이용할 수 있는 재화 또는 서비스를 의미한다.', detailed_meaning = '공공재는 모든 개인이 공동으로 이용할 수 있는 재화 또는 서비스를 의미한다. 국방·경찰·소방·공원·도로 등과 같이 정부에 의해서만 공급할 수 있는 것이라든가 또는 정부에 의해서 공급되는 것이 바람직하다고 사회적으로 판단되는 재화 또는 서비스가 이에 해당한다. 공공재에는 보통 시장가격은 존재하지 않으며 수익자부담 원칙도 적용되지 않는다. 따라서 공공재 규모의 결정은 정치기구에 맡길 수밖에 없다. 공공재의 성질로는 어떤 사람의 소비가 다른 사람의 소비를 방해하지 않고 여러 사람이 동시에 편익을 받을 수 있는 비경쟁성·비선택성, 대가를 지급하지 않은 특정 개인을 소비에서 제외하지 않는 비배제성 ㄱ등을 들 수 있다.', related_words = ARRAY['자유재']::text[] WHERE id = 49;  -- 공공재
UPDATE public.words SET meaning = '산업연관표는 투입산출표(Input-Output Tables)와 공급사용표(Supply and Use Tables)로 구성되는데, 투입산출표는 상품을 기준으로, 공급사용표는 산업을 기준으로', detailed_meaning = '산업연관표는 투입산출표(Input-Output Tables)와 공급사용표(Supply and Use Tables)로 구성되는데, 투입산출표는 상품을 기준으로, 공급사용표는 산업을 기준으로 생산내역을 나타낸 표이다. 투입산출표는 상품을 기준으로 하기 때문에 하나의 산업에 서 한 상품만을 생산한다고 가정하고 있어 경제 현실이 제대로 반영되지 못하는 문제점을 갖고 있는 반면, 공급사용표는 경제 현실이 잘 반영될 뿐만 아니라 국민소득통계, 국민대차대조표 등 국민경제 통계들 간의 정합성 유지에도 중요한 역할을 한다. 공급사용표는 공급표(Supply Table)와 사용표(Use Table)로 구성된다. 공급표의 세로 방향은 각산업에서 어떤 상품이 얼마만큼 생산(또는 공급)되는가를 기록하여 산업별 상품의 생산구조를 알려준다. 가로 방향은 각 상품이 어느 산업에서 얼마만큼 생산되어 공급되는가를 표시하여 상품의 산업별 공급구조를 나타내고 있다. 한편 사용표의 세로방향은 각 산업의 생산활동에 투입되는 중간재와 부가가치를 기록하고 있으며, 가로 방향은 공급된 상품이 각 산업별 중간수요 또는 소비, 고정자본형성, 재고증감, 수출 등 최종수요로 사용된 내역을 나타낸다.', related_words = ARRAY['국민계정체계(SNA)','국민대차대조표']::text[] WHERE id = 51;  -- 공급사용표(SUT)
UPDATE public.words SET meaning = '공동부유(共同富裕, Common Prosperity)는 시진핑 중국 국가주석이 2021년 이후 강조한 주요 정책 방향 중 하나로서 소수만 부유해지는 것이 아니라 사회 전체가 균형 있게 번영하고', detailed_meaning = '공동부유(共同富裕, Common Prosperity)는 시진핑 중국 국가주석이 2021년 이후 강조한 주요 정책 방향 중 하나로서 소수만 부유해지는 것이 아니라 사회 전체가 균형 있게 번영하고 부를 나누어 모든 국민이 함께 잘사는 사회를 만들자는 것을 의미한다. 즉 독과점기업의 불공정 거래행위 시정, 기업의 사회 기부 독려, 부동산세 도입 등을 통해 부의 불균형을 해소하고 국민 전체의 삶의 질 향상을 도모하려는 정책이다. 공동부유가 핵심정책으로 등장한 배경으로는 중국경제가 개혁·개방 이후 고도성장을 달성하는 데 성공하였으나 경제적 불평등이 심화되어 체제 정당성과 안정을 위협하는 수준에 이른 점을 들 수 있다.', related_words = ARRAY['독점/과점']::text[] WHERE id = 53;  -- 공동부유
UPDATE public.words SET meaning = '광의통화(M2)는 경제 내에 유통되는 화폐규모를 측정하는 통화지표의 하나로서, 지급결제기능을 중시하여 작성하는 협의통화(M1) 외에도 약간의 이자소득 손실을 감수한다면언제든지 인출이 가능한', detailed_meaning = '광의통화(M2)는 경제 내에 유통되는 화폐규모를 측정하는 통화지표의 하나로서, 지급결제기능을 중시하여 작성하는 협의통화(M1) 외에도 약간의 이자소득 손실을 감수한다면언제든지 인출이 가능한 가치저장기능이 있는 금융상품까지 포함된다. 만기 2년 이내의 정기예금, 정기적금, 금융채, 수익증권 등 단기간 내 현금화가 가능한 금융상품이 이에 해당한다. M2는 중장기적인 통화량 흐름과 금융시장의 유동성 상황을 파악하는 데 활용되며, 중앙은행의 통화정책 수립에도 중요한 기준이 된다. 일반적으로 M2가 증가하면 시중에 돈이 많이 풀렸다는 의미로 해석되며, 이는 물가 상승 압력이나 경기과열 가능성과도 연결된다. M2는 협의통화보다 유동성은 낮지만, 실제 경제에서 통화량을 측정할 때 가장 널리 사용되는 지표다.', related_words = ARRAY['통화지표','통화량']::text[] WHERE id = 55;  -- 광의통화(M2)
UPDATE public.words SET meaning = '교환사채(EB; Exchangeable Bond)란 사채권자의 의사에 따라 교환사채 발행기업이 보유하고 있는 타사 주식 등 여타의 유가증권과 교환할 수 있는 선택권이 부여된 사채를 말한다.', detailed_meaning = '교환사채(EB; Exchangeable Bond)란 사채권자의 의사에 따라 교환사채 발행기업이 보유하고 있는 타사 주식 등 여타의 유가증권과 교환할 수 있는 선택권이 부여된 사채를 말한다. 발행하는 채권에 주식이 연계되어 있다는 점에서 발행회사의 신주를 일정한 조건으로 매수할 수 있는 신주인수권부사채(BW; Bonds with Warrant)나, 발행회사의 주식으로 전환할 수 있는 권리가 부여된 전환사채(CB; Convertible Bond) 등과 함께 주식연 ㄱ계증권으로 불린다. 발행회사가 보유하는 교환대상 유가증권은 상장유가증권으로 제한되고 있으며 증권예탁원에 의무적으로 예탁되어야 한다. 발행회사는 낮은 이자율로 사채를 발행하여 금융비용 부담을 덜 수 있어 회사채 발행을 통한 기업자금조달을 촉진할 수 있는 장점이 있다. 반면에 투자자의 입장에서도 비교적 안정적인 데다 미래의 주식가격 상승에 따른 시세차익을 기대할 수 있음에 따라 유리한 투자수단이 된다. 교환이 이루어질때 발행기업의 자산과 부채가 동시에 감소한다. 신규자금 유입이 없다는 점에서 신주인수권부사채(BW)와는 다르고 신주발행에 따른 자본금의 증가가 없다는 점에서 전환사채 (CB)와도 다르다.', related_words = ARRAY['신주인수권부사채(BW)','전환사채(CB)']::text[] WHERE id = 56;  -- 교환사채(EB)
UPDATE public.words SET meaning = '국가의 경제활동도 민간의 경제활동과 마찬가지로 금전 수수를 수반하게 되는데 이와 같은 경제활동에 수반되는 일체의 현금을 통상 국고금이라 한다.', detailed_meaning = '국가의 경제활동도 민간의 경제활동과 마찬가지로 금전 수수를 수반하게 되는데 이와 같은 경제활동에 수반되는 일체의 현금을 통상 국고금이라 한다. 우리나라에서는 국고금의 출납사무를 중앙은행인 한국은행이 담당하고 있다. 그러나 한국은행의 한정된 조직과 인력만으로는 전국의 국고금 납부자에게 충분한 편의를 제공하기 어렵기 때문에 한국은행은 금융기관과의 계약을 통해 금융기관 영업점을 국고 대리점으로 지정하여 국고금 수납사무를 위탁하고 있다. 국고대리점은 국고수납대리점과 국고금수납점으로 구분하는데 기능상 차이는 없으며 계약방식의 차이에 의해서 구분된다. 국고수납대리점은 은행 영업점및 신용협동기구의 중앙회가 이에 해당되며 국고금수납점은 신용협동기구의 중앙회 등이 산하 회원조합(금고)에 국고금 수납사무를 재위탁한 영업점을 말한다. 2025년 6월말 현재국고대리점은 총 16,467개(국고수납대리점 5,647개, 국고금수납점 10,820개)가 있다. ㄱ', related_words = '{}'::text[] WHERE id = 65;  -- 국고대리점
UPDATE public.words SET meaning = '국고수표는 지출관이 국고금 지출을 위하여 발행하는 수표로 과거 국고금의 기본지급수단이었으나 2003년 1월 1일 「국고금관리법」의 시행으로 국고금 실시간 전자이체제도가 실시됨으로써 국고금', detailed_meaning = '국고수표는 지출관이 국고금 지출을 위하여 발행하는 수표로 과거 국고금의 기본지급수단이었으나 2003년 1월 1일 「국고금관리법」의 시행으로 국고금 실시간 전자이체제도가 실시됨으로써 국고금 지급방식이 국고수표 사용방식에서 수취인의 예금계좌로 바로 입금되도록 변경된 이후 사용하지 않고 있다. 다만 금융기관의 전산장애 등과 같은 비상시를 위해 폐지하지 않고 있다.', related_words = ARRAY['국고금 실시간 전자이체','국고전산망']::text[] WHERE id = 66;  -- 국고수표
UPDATE public.words SET meaning = '2003년 1월 한국은행이 국고업무를 전자적으로 처리하기 위하여 구축한 전산망을 국고 전산망이라고 말하며 정부(디지털예산·회계시스템(dBrain+)), 한국은행, 금융기관(우정사업본부 포함) 및', detailed_meaning = '2003년 1월 한국은행이 국고업무를 전자적으로 처리하기 위하여 구축한 전산망을 국고 전산망이라고 말하며 정부(디지털예산·회계시스템(dBrain+)), 한국은행, 금융기관(우정사업본부 포함) 및 금융결제원의 전산시스템을 서버접속 방식으로 연결한다. 국고전산망을 이용하여 취급하는 업무는 OLTP(On-line Real Time Transaction Processing) 방식으로 처리하는 실시간 전자이체업무와 FTP(File Transfer Protocol) 방식으로 처리하는 파일 송수신업무가 있다. 국고전산망 참가대상 기관은 기획재정부, 한국은행과 국고수납대리점계약을 체결한 금융기관 및 한국은행 이외의 국고금수납기관(체신관서, 금융결제원)으로 한정하고 있다. 국고전산망 운영시간은 오전 9시부터 오후 4시까지이다.', related_words = ARRAY['국고금 실시간 전자이체']::text[] WHERE id = 67;  -- 국고전산망
UPDATE public.words SET meaning = '국내총생산(GDP; Gross Domestic Product)은 한 나라의 영역 내에서 가계, 기업, 정부등 모든 경제주체가 일정 기간 생산활동에 참여하여 창출한 부가가치 또는 최종 생산물을', detailed_meaning = '국내총생산(GDP; Gross Domestic Product)은 한 나라의 영역 내에서 가계, 기업, 정부등 모든 경제주체가 일정 기간 생산활동에 참여하여 창출한 부가가치 또는 최종 생산물을 시장가격으로 평가한 합계로서 여기에는 국내에 거주하는 비거주자(외국인)에게 지급되는 소득도 포함된다. 한편 가격의 적용방법에 따라 명목GDP(Nominal GDP)와 실질 GDP(Real GDP)로 구분되는데, 명목GDP는 국가경제의 규모나 구조 등을 파악하는 데사용되며 실질GDP는 경제성장, 경기변동 등 전반적인 경제활동의 흐름을 분석하는 데이용된다.', related_words = ARRAY['국민총소득(GNI)']::text[] WHERE id = 69;  -- 국내총생산(GDP)
UPDATE public.words SET meaning = '국민대차대조표(National Balance Sheet)는 특정 시점에서 국민경제 또는 비금융법인기업, 금융법인기업, 일반정부, 가계 및 비영리단체, 국외 등 각 경제주체가 보유하고 있는 유·무형', detailed_meaning = '국민대차대조표(National Balance Sheet)는 특정 시점에서 국민경제 또는 비금융법인기업, 금융법인기업, 일반정부, 가계 및 비영리단체, 국외 등 각 경제주체가 보유하고 있는 유·무형 실물자산 및 금융자산/부채의 가액과, 자산에서 부채를 차감한 순자산을 기록한 스톡통계이다. 즉, 국민대차대조표는 경제주체별로 처분가능한 금융 및 비금융자산의 가 액 등 재산상태를 나타내며 그중 순자산(net wealth)은 해당 경제주체의 재산상태를 집약한 정보라 할 수 있다. 특히 국민경제 전체의 순자산은 흔히 국부(national wealth)라 불리며 국내경제가 보유한 비금융자산의 현재가액과 국외부문에 대한 순금융자산청구권의 합계와 동일하다. 국민대차대조표에 기록되는 자산 항목은 크게 비금융자산과 금융자산/ 금융부채로 구성된다. 비금융자산의 경우 생산과정을 통해 산출된 것이냐의 여부에 따라생산자산과 비생산자산으로 나누어지고, 비금융비생산자산에는 생산과정을 거치지 않고 자연적으로 존재하는 토지, 지하자원, 입목 등이 포함된다. 한편, 국민대차대조표는 기초대차대조표, 기말대차대조표 및 대차대조표 증감계정으로 구성되어 있어 각 경제주체의 재산이 기간 중에 어떠한 요인에 의해 변동하였는지를 몇 가지로 분해하여 보여주는 표로 서 SNA 내에서 소득창출 과정 등을 기록한 플로계정과 자산의 축적상태를 기록한 스톡계정을 통합하는 기능을 수행한다. 2014년에 국민대차대조표를 신규 편제함으로써 우리나 라는 SNA(System of National Accounts) 이행의 최상위인 6단계를 달성하게 되었고 완전한 국민계정체계를 구현하게 되었다.', related_words = ARRAY['국민계정체계(SNA)']::text[] WHERE id = 72;  -- 국민대차대조표
UPDATE public.words SET meaning = '국민소득(NI; National Income)은 한 나라 국민이 제공한 생산요소에서 발생한 소득의 총액, 즉 노동에 대한 대가인 피용자보수와 자본 및 경영에 대한 대가인 영업잉여의 합계로서', detailed_meaning = '국민소득(NI; National Income)은 한 나라 국민이 제공한 생산요소에서 발생한 소득의 총액, 즉 노동에 대한 대가인 피용자보수와 자본 및 경영에 대한 대가인 영업잉여의 합계로서 고정자본소모와 순생산 및 수입세는 포함되지 않는다. 즉 한 나라 국민이 벌어들인순수한 소득을 나타내는 지표로서 다음과 같이 산출한다. 국민소득(NI) = 국민총소득 - 고정자본소모 - 생산 및 수입세 + 보조금= 국민순소득 - 생산 및 수입세 + 보조금= 국민순소득 - 순생산 및 수입세 ㄱ = 피용자보수 + 영업잉여= 임금 + 지대 + 이자 + 이윤', related_words = ARRAY['국민총소득(GNI)']::text[] WHERE id = 74;  -- 국민소득
UPDATE public.words SET meaning = '일정기간 동안 보험료를 납부하면 노후에 연금을 지급받아 기본적인 생활을 보장받을 수있도록 설계된 공적 연금 제도이다.', detailed_meaning = '일정기간 동안 보험료를 납부하면 노후에 연금을 지급받아 기본적인 생활을 보장받을 수있도록 설계된 공적 연금 제도이다. 현재 우리나라는 국민연금공단이 운영 주체가 되어만 18세 이상 ~ 60세 미만의 대한민국 국민을 대상으로 매달 소득의 일정 비율을 납부받고 있으며, 일정 연령에 도달해야 연금을 수령할 수 있다. 국민연금으로 받을 수 있는 급여로는 노후 생활비로 지급되는 노령연금, 불의의 사고나 질병으로 장애가 생겼을 때지급되는 장애연금, 가입자가 사망할 경우 유족에게 지급되는 유족연금 등이 있다. 국민연금은 고령화 사회에서 은퇴 이후 소득이 줄어드는 사람들을 위한 안정적 소득원으로 개인연금, 퇴직연금과 함께 노후 대비의 핵심축이 된다. 다만 출산율 저하와 고령화로 인해국민연금 기금이 고갈될 수 있다는 우려가 높아지면서 수급 개시 연령 상향, 보험료 인상등의 필요성이 대두되고 있다.', related_words = ARRAY['합계출산율','인구고령화']::text[] WHERE id = 75;  -- 국민연금
UPDATE public.words SET meaning = '국부펀드(Sovereign Fund)는 주로 투자수익을 목적으로 다양한 종류의 국내외 자산에 투자·운용하는 국가 보유 투자기금을 말한다.', detailed_meaning = '국부펀드(Sovereign Fund)는 주로 투자수익을 목적으로 다양한 종류의 국내외 자산에 투자·운용하는 국가 보유 투자기금을 말한다. 국부펀드는 운용목적이나 투자자산 선택 등에 서 사모펀드, 연기금 등과 유사한 면이 있으나 소유권이 민간이 아니라 국가에 있다는 점에서 근본적인 차이가 있다. 국부펀드의 종류는 재원을 조달하는 방법에 따라 상품펀드와 비상품펀드로 나누어진다. 상품펀드의 재원은 국가기관의 원자재 수출대금 또는 민간기업의 원자재 수출소득에 대한 세금 등 정부의 외화수입으로 조달되며 비상품펀드의 경우는 국제수지 흑자로 축적된 외환보유액, 공적연기금, 재정잉여금 등으로 조달된다. 국부펀드라는 용어가 널리 사용되기 시작한 것은 2005년경이나, 1953년 쿠웨이트투자청 등 이 있었으며 대부분의 국부펀드는 1970년대 이후에 만들어졌다. 2000년대 이후 국부펀드는 아시아와 중동을 비롯한 신흥시장국가들이 주로 조성하여 왔다. 이들은 석유수출과 경상수지 흑자를 통해 벌어들인 외환보유액을 이용하여 국부펀드를 설립하여 운용하고 있다. 우리나라는 2005년 7월 한국투자공사(KIC; Korea Investment Corporation)를 설립하였다. 이후에도 2007년 중국에서 중국투자공사(CIC; China Investment Corporation), 2008년에는 러시아에서 러시아 National Welfare Fund 등이 설립되었다.', related_words = ARRAY['외환보유액','헤지펀드']::text[] WHERE id = 78;  -- 국부펀드
UPDATE public.words SET meaning = '국외투자율은 국민총처분가능소득(GNDI; Gross National Disposable Income) 중 총저축에서 국내투자를 차감한 부분이 차지하는 비율을 의미한다.', detailed_meaning = '국외투자율은 국민총처분가능소득(GNDI; Gross National Disposable Income) 중 총저축에서 국내투자를 차감한 부분이 차지하는 비율을 의미한다. 한 나라 국민 전체가 소비하거나 저축할 수 있는 소득을 국민총처분가능소득(GNDI; Gross National Disposable Income)이라고 하는데, 이는 국민총소득(GNI; Gross National Income)에 국외순수취경상이전을 더한 것이다. 여기서 국외순수취경상이전이 란 교포송금 등과 같이 생산활동과는 관계없이 외국으로부터 받은 소득(국외수취경상이 전)에서 무상원조 등으로 외국에 지급한 소득(국외지급경상이전)을 뺀 금액이다. GNDI에서 최종소비지출을 빼면 총저축을 얻을 수 있다. 이러한 총저축은 투자를 위한 자금으로 이용된다. 투자는 국내투자와 국외투자로 나눌 수 있는데, 총저축이 국내투자보다 많아 외국에 자금을 투자하는 경우 국외투자가 플러스(+) 값을 가진다. 반대로 총저축으로 국내투자를 충당할 수 없어서 외국으로부터 자금을 차입하면 국외투자가 마이너스 (-) 값을 갖게 된다. 한편 국내투자, 총저축을 GNDI로 나누어 백분율로 구한 값을 각각 국내총투자율, 총저축률이라고 하는데, 국내총투자율과 국외투자율을 합한 값을 총투자율이라고 하며, 총투자율은 총저축률과 같은 값이 된다. GNDI = 최종소비지출 + 총저축 총투자율(%) = 국내총투자율(%) + 국외투자율(%) 국내총투자율(%) = (국내총투자/GNDI) × 100 국외투자율(%) = (국외투자/GNDI) × 100', related_words = ARRAY['국민총처분가능소득','총투자율','국내총투자율','총저축률']::text[] WHERE id = 79;  -- 국외투자율
UPDATE public.words SET meaning = 'BIS(BIS; Bank for International Settlements)는 1930년 헤이그협정을 모체로 설립된 세계에서 가장 오래된 국제금융기구로서 중앙은행 간 정책협력을 주요기능으로', detailed_meaning = 'BIS(BIS; Bank for International Settlements)는 1930년 헤이그협정을 모체로 설립된 세계에서 가장 오래된 국제금융기구로서 중앙은행 간 정책협력을 주요기능으로 하고 있으며 현재 60개 중앙은행이 회원으로 참여하고 있다. BIS는 중앙은행 간 협력체로서의 기능 수행에 중점을 두고 있으나 국제금융거래의 원활화를 위한 편의 제공, 국제결제업무와 관련한 수탁자 및 대리인으로서의 역할도 수행하고 있다. BIS는 최고의사결정기구인 총회, 운영을 담당하는 이사회, 일반업무를 관장하는 집행부로 구성되어 있으며 중앙은행간 정보교환기능 제고를 위해 총재회의, 특별회의, 각종 산하 위원회 회의 등을 수시로 개최하고 있다. 또한, 아시아지역과 아메리카지역 중앙은행과의 관계를 증진하기 위하여 홍콩 및 멕시코에 지역사무소를 개설하였다. 한국은행은 1975년 연차총회에 옵서버 자격으로 참석한 이래 국제통화협력을 위해 노력한 결과 1997년 1월 14일 정식회원으로 가입하였다.', related_words = '{}'::text[] WHERE id = 80;  -- 국제결제은행(BIS)
UPDATE public.words SET meaning = '특정 국가나 지역이 국제금융시장으로 기능하기 위해서는 자국 통화의 국제통용성, 상대적으로 우월한 기초경제력, 고도로 발달된 금융시장과 다양한 장단기 금융수단의 자유로 운 거래, 전 세계시장 정보의', detailed_meaning = '특정 국가나 지역이 국제금융시장으로 기능하기 위해서는 자국 통화의 국제통용성, 상대적으로 우월한 기초경제력, 고도로 발달된 금융시장과 다양한 장단기 금융수단의 자유로 운 거래, 전 세계시장 정보의 신속 저렴한 공급, 세계적인 상품 및 서비스거래의 중심지등의 요건을 두루 갖추어야 한다. 국제금융중심지는 이러한 국제금융시장의 요건을 갖추고 있어 세계적 금융기관들이 본점, 지점, 현지법인의 형태로 영업망을 집중시킴으로써대량의 국제금융거래가 지속적, 반복적으로 이루어지는 장소를 말한다. 대표적인 국제금 ㄱ융중심지로는 뉴욕, 런던, 동경 등이 있다. 한편 역외 국제금융중심지는 주로 비거주자로 부터 자금을 조달하여 비거주자를 대상으로 운영되는 금융중개시장으로, 조세 및 금융규제 면에서 특혜를 부여하여 인위적으로 창설한 금융 중심지이다. 홍콩, 싱가포르, 룩셈부르크 등이 대표적이다.', related_words = ARRAY['국제금융시장']::text[] WHERE id = 82;  -- 국제금융중심지
UPDATE public.words SET meaning = '원유는 전세계적으로 수백 종이 거래되고 있다.', detailed_meaning = '원유는 전세계적으로 수백 종이 거래되고 있다. 이중 국제원유시장의 대표 유종은 미국 서부텍사스유(WTI; West Texas Intermediate), 영국 브렌트유 및 아랍에미레이트 (UAE) 두바이유의 세 가지이다. WTI는 북미, 브렌트유는 유럽 및 아프리카, 두바이유는 중동을 각각 대표하는 기준유가를 정하는 유종으로 사용되고 있다. 국제원유가격은 1980 년대 중반까지는 석유수출국기구(OPEC; Organization of the Petroleum Exporting Countries)의 발표가격을 기준으로 사용하였다. 그러나 석유파동 등으로 인한 국제원유가격의 변동성을 회피하기 위해 선물거래가 활성화되면서 선물가격이 실질적인 현물유가 의 기준역할을 하게 되었다. 우리나라에서는 수입 비중이 높은 두바이유의 가격이 원유도 ㄱ입단가에 큰 영향을 미친다. 국제석유시장에서는 선물시장 거래량이 가장 많고 광범위한 지역으로 수출되는 브렌트유의 가격이 가장 높은 대표성을 갖고 있다. 국제원유가격은 장기적으로 원유 수요와 공급에 의해 결정되나 원유 공급지의 지정학적 리스크와 기상, 미달러화 가치, 주요국 석유재고의 변동 등 많은 요인의 영향을 받는다.', related_words = ARRAY['선물거래']::text[] WHERE id = 86;  -- 국제원유가격
UPDATE public.words SET meaning = '국제증권감독기구(IOSCO; International Organization of Securities Commissions) 는 전 세계의 증권 규제기관들이 모인 국제적인 기구로서 130여개', detailed_meaning = '국제증권감독기구(IOSCO; International Organization of Securities Commissions) 는 전 세계의 증권 규제기관들이 모인 국제적인 기구로서 130여개 국가가 회원국으로 참여하고 있다. 증권 시장의 안전성과 공정성을 보장하고, 투자자 보호를 위해 국제적인 규제 기준을 마련하는 것을 목표로 하고 있으며 전 세계 증권시장의 95% 이상이 IOSCO가 제정한 기준을 따르고 있다. IOSCO는 1983년 아메리카 대륙의 11개 증권감독기구들의 연합체로 출발하였는데, IOSCO의 ‘증권규제의 목적과 원칙’(Objectives and Principles of Securities Regulation)은 G20와 국제금융기구(IMF), 세계은행(World Bank) 등에서 도 핵심 기준으로 받아들여지고 있다. 한편 우리나라는 금융감독당국인 금융위원회와 금융감독원이 참여하고 있다.', related_words = ARRAY['금융시장인프라(FMI)']::text[] WHERE id = 87;  -- 국제증권감독기구(IOSCO)
UPDATE public.words SET meaning = '국제투자대조표(IIP; International Investment Position)는 일정 시점 현재 한 나라 거주자의 비거주자에 대한 금융자산(대외투자) 및 금융부채(외국인투자) 잔액을 기록한', detailed_meaning = '국제투자대조표(IIP; International Investment Position)는 일정 시점 현재 한 나라 거주자의 비거주자에 대한 금융자산(대외투자) 및 금융부채(외국인투자) 잔액을 기록한 통계표로서 국제수지의 금융계정(직접투자, 증권투자, 파생금융상품, 기타투자, 준비자산) 과 포괄범위가 동일하다. 일정 시점의 대외금융자산/부채 잔액은 거래일 이후 환율이나 주가변동 등으로 인한 가치평가분이 포함되어 있기 때문에 금융계정의 거래 누계액과 차이가 있을 수 있다. 한편 국제투자대조표의 대외금융자산/부채에서 지분성투자(직접투자내 지분투자, 증권투자 내 지분증권, 기타투자 내 기타지분)와 파생금융상품을 제외할 경 ㄱ우 대외채권·채무 통계와 개념적으로 일치한다. 국제투자대조표는 한국은행에서 매분기작성하여 발표하고 있다.', related_words = ARRAY['국제수지(BOP)']::text[] WHERE id = 90;  -- 국제투자대조표(IIP)
UPDATE public.words SET meaning = '국제회계기준(IFRS; International Financial Reporting Standards)은 기업의 회계처리와 재무제표에 대한 국제적 정합성을 높이기 위해서', detailed_meaning = '국제회계기준(IFRS; International Financial Reporting Standards)은 기업의 회계처리와 재무제표에 대한 국제적 정합성을 높이기 위해서 국제회계기준위원회(IASB; International Accounting Standards Board)가 제정한 회계처리기준을 말한다. 자본시장 개방 등 전세계의 글로벌화 진전 등으로 국제적으로 통일된 회계기준의 필요성이 증가 한 데다, 특히 2002년 발생한 엔론, 월드콤 등의 회계부정사건을 계기로 국제적으로 회계투명성에 대한 요구도 커짐에 따라 국제회계기준이 마련되었다. 국제회계기준의 핵심원칙으로는 ① 원칙중심의 기준회계 ② 연결재무제표 중심 보고 ③ 공정가치 평가 ④ 경제적실질에 기초한 회계처리 등을 들 수 있다. 회계기준 단일화 추세에 따라 전 세계 100여 개국가에서 사용 중이며 우리나라도 국내 회계 투명성에 대한 국제적 신뢰도 저하가 자본시장에 부정적인 영향을 미칠 수 있다는 우려에서 2007년 3월 「국제회계기준(IFRS) 도입로드맵」을 발표하였으며 이후 희망기업은 2009년부터, 상장회사는 2011년부터 전면 도 입되었다. 2024년 4월에는 손익의 원천을 명시하여 성과정보의 비교가능성을 높이는 방향으로 재무제표의 표시 방식을 변경하는 IFRS 18이 신규 제정되어 2027년부터 전면 적용될 예정이다.', related_words = '{}'::text[] WHERE id = 91;  -- 국제회계기준
UPDATE public.words SET meaning = '그린본드는 조달 자금을 기후 및 환경 관련 사업에 사용하는 것을 전제로 발행되는 특수목적 채권이다.', detailed_meaning = '그린본드는 조달 자금을 기후 및 환경 관련 사업에 사용하는 것을 전제로 발행되는 특수목적 채권이다. 특징은 조달 자금의 사용처(use of proceeds)에 있고 발행자가 그린본드원칙(GBP; Green Bond Principle)에 따라 채권을 발행하는 경우 재량으로 이름을 지을 수 있다. 그린본드는 채권의 구조에 따라 ① 그린사업 채권 ② 그린사업 수익 채권 ③ 그린 프로젝트 채권 ④ 그린 유동화 채권으로 분류된다. 그린본드는 2007년 최초 발행(6억유로)된 이후 초기에는 주로 EIB, World Bank 등 국제기구가 글로벌 환경보호, 균형성장등과 관련해 발행을 주도하였으나 최근에는 정부기관, 기업 및 금융기관 등으로 발행기관의 범위가 확대되어 가파른 성장세를 시현하고 있다. 그린본드의 발행자는 자본비용, 기업홍보, 사업추진 용이성 측면에서 편익을 누릴 수 있다. 그린본드는 사회적 책임 투자 기회를 제공하는 한편 여타 채권과 발행방식 및 구조가 동일하여 기존 채권 포트폴리오에 쉽게 융화가 가능한 장점이 있다. 국제자본시장협회(ICMA)가 그린본드 원칙(GBP)의 운영 및 관리를 담당하고 있다.', related_words = '{}'::text[] WHERE id = 97;  -- 그린본드
UPDATE public.words SET meaning = '집합투자기구(MMF·채권형·혼합형 펀드 등), RP 거래, 유동화기구 등과 같이 은행시스템밖에서 신용중개기능을 수행하지만 은행 수준의 건전성 규제와 예금자보호가 적용되지않는 기관 또는 활동을', detailed_meaning = '집합투자기구(MMF·채권형·혼합형 펀드 등), RP 거래, 유동화기구 등과 같이 은행시스템밖에서 신용중개기능을 수행하지만 은행 수준의 건전성 규제와 예금자보호가 적용되지않는 기관 또는 활동을 이르는 용어이다. 그림자금융(Shadow Banking)은 은행의 전통적인 자금중개기능을 보완하는 한편 금융업의 경쟁을 촉진함으로써 효율적인 신용 배분에 기여하는 순기능을 발휘한다. 그러나 글로벌 금융위기 과정에서 느슨한 규제 하에 과도한 리스크 및 레버리지 축적, 은행시스템과의 직·간접적 연계성 등을 통해 시스템 리스크를 촉발·확산시킨 원인 중 하나로 지목되기도 하였다. 이에 따라 금융안정위원회(FSB), 바젤은행감독위원회(BCBS) 등 국제금융감독기준 제정기구를 중심으로 그림자금융에 대한 모니터링 체계 구축 및 규제개혁 논의가 진행되어왔다. 한편 FSB는 그림자금융의 순기능 등 을 고려하여 2018년 10월부터 “그림자금융(Shadow Banking)”이라는 용어를 보다 중립적인 의미가 담긴 “비은행금융중개(Non-Bank Financial Intermediation)”로 변경하여사용하고 있다.', related_words = '{}'::text[] WHERE id = 98;  -- 그림자금융/비은행금융중개(NBFI)
UPDATE public.words SET meaning = '미국 의회가 제정한 법으로 공식 명칭은 「1933년 은행법(Banking Act of 1933)」이다.', detailed_meaning = '미국 의회가 제정한 법으로 공식 명칭은 「1933년 은행법(Banking Act of 1933)」이다. 민주당 상원의원 카터 글래스(Carter Glass)와 민주당 하원의원 헨리 B. 스티걸(Henry B. Steagall)이 공동으로 제안하였기 때문에 통상 「글래스-스티걸법(Glass-Steagall Act)」이라불린다. 은행들의 고객 자산을 이용한 방만한 투자행위가 1929년의 주가폭락과 그에 이은 금융위기 및 대공황의 원인 중 하나로 지목됨에 따라 ‘은행개혁’과 ‘투기규제’를 목적으로 동 법이 제정되었다. 동 법의 핵심 내용은 기존 은행을 상업은행과 투자은행으로 구분하고 이들의 업무를 엄격하게 분리하려는 것이다. 이에 따라 상업은행은 증권의 발행 및 인수가 금지되고 증권 관련 자회사 보유도 금지되었으며, 투자은행은 일반인으로부터 예금을 받을 수 없고, 상업은행과 투자은행간에 임직원의 겸직이 금지되었다. 또한 동 법을 통해 연방예금보험공사(FDIC; Federal Deposit Insurance Corp.)를 설립하여 연방예금보험제도를 도입하고 금융에 대한 연방준비제도의 통제를 강화하였으며 연방공개시장위원회(FOMC)를 설치하였다. 동 법 시행 이후 미국에서는 상업은행과 투자은행의 영역이 엄격히 분리되어 골드만삭스·모건스탠리·메릴린치 등은 투자은행으로, JP모건·뱅크오브아메리카·시티뱅크 등은 대형 상업은행으로 성장하였다. 동 법에 대해서는 경쟁을 제한하여 금융산업의 비효율성을 초래하였다는 부정적 평가와 수십 년에 걸친 미국 금융시스템의 안정에 기여하였다는 긍정적 평가가 공존하고 있다. 1999년 11월 금융산업 경쟁력 강화를 명분으로 내세운 클린턴 행정부의 정책기조와 월스트리트 상업은행들의 로비력이 맞물리면서 ‘상업은행의 증권 관련 자회사 보유’ 및 ‘상업은행과 투자은행의 임직원 겸직’허용을 주요 내용으로 하는 그램-리치-블라일리법(Gramm-Leach-Bliley Act)이 제정됨으로써 글래스-스티걸법의 핵심 조항은 폐지되었다.', related_words = ARRAY['그램-리치-블라일리법','투자은행']::text[] WHERE id = 100;  -- 글래스-스티걸법
UPDATE public.words SET meaning = '금리스왑(IRS; Interest Rate Swaps)이란 금리변동위험 헤지 및 차입비용 절감 등을 위하여 거래당사자간에 원금교환 없이 정기적으로 통상 3개월마다 변동금리(91일물 CD금리) 와', detailed_meaning = '금리스왑(IRS; Interest Rate Swaps)이란 금리변동위험 헤지 및 차입비용 절감 등을 위하여 거래당사자간에 원금교환 없이 정기적으로 통상 3개월마다 변동금리(91일물 CD금리) 와 고정금리(IRS금리)를 교환하는 거래를 말한다. 이때 고정금리를 지급하는 대신 변동금리를 수취하는 거래를 금리스왑 pay거래라 하며 반대로 고정금리를 수취하는 대신 변동금리를 지급하는 거래를 금리스왑 receive거래라 한다. 거래단위와 만기는 제한이 없지만 통상 100억원, 만기 1~5년 거래가 주를 이룬다. 일반적으로 금리스왑은 고정금리부 자산과 고정금리부 부채의 듀레이션이 불일치함에 따라 발생하는 금리변동위험을 헤지하는데이용된다. 예를 들어 고정금리부 자산이 고정금리부 부채보다 많은 경우 고정금리부 부채를 늘릴 필요가 있는데 이때 금리스왑거래를 통해 채권매도와 같은 효과를 내는 금리스왑 pay거래를 실시하면 금리변동위험이 감소한다. 금리스왑도 향후 금리변동에 따른 위험을 회피하기 위한 헤지거래와 향후 금리 방향을 예상하여 이익을 추구하는 투기적 거래가 있다. 앞서 제시한 예시는 헤지거래에 해당한다. 자신의 자산·부채 포지션과 관계없이 금리하락을 예상하여 수익을 추구하는 경우에는 금리스왑 receive거래를, 금리 상승을 예상하여 수익을 추구하는 경우에는 금리스왑 pay거래를 하게 되는데 전형적인 투기적 거래에 해당한다. 금리스왑시장에서는 금리스왑 스프레드라는 용어가 자주 등장한다. 이는 동일만기 「IRS금리-국고채금리(무위험채권)」를 의미한다. 금리스왑 스프레드는 향후 금리전망, 거래상대방의 신용위험 등 다양한 요인에 의해 변동된다. 예를 들어 스왑딜러가 향후시장금리가 하락할 것으로 예상하여 변동금리를 지급하는 대신 고정금리를 수취하는 금리스왑 receive거래를 하는 경우 고정금리 수취 수요가 증가함에 따라 IRS금리가 하락하면서 금리스왑 스프레드는 축소된다.', related_words = '{}'::text[] WHERE id = 105;  -- 금리스왑
UPDATE public.words SET meaning = '금리자유화란 금리규제를 철폐함으로써 금리가 시장의 자금수급에 따라 자유로이 결정될수 있도록 하는 조치이다.', detailed_meaning = '금리자유화란 금리규제를 철폐함으로써 금리가 시장의 자금수급에 따라 자유로이 결정될수 있도록 하는 조치이다. 금융시장의 대표적인 가격변수인 금리를 제한하는 것은 역사적으로 보아 미국 등 다수의 국가에서 금융불안이 반복적으로 발생함에 따라 금융안정을 도 모하기 위해 도입한 금융규제의 하나이다. 이러한 구조적 금융규제로는 금리규제 이외에 업무영역규제, 진입제한 등이 있다. 그러나 1970~80년대 인플레이션이 심화되면서 은행의 자금중개가 위축되는 이른바 디스인터미디에이션(disintermediation)이 발생하는 가 운데 금융규제를 우회하는 금융혁신이 진전되고 금융자유화가 추진되면서 각국은 금리규제를 단계적으로 철폐하였다. 대표적으로 미국의 경우 ‘레귤레이션 큐(Q)’라는 연준 규정에 의해 은행예금 최고금리가 제한되었는데, 1980년대 일련의 자유화조치 등으로 금리자유화가 진전되었다. 한국은 금융기관 간 경쟁을 촉진함으로써 금융의 효율성을 높이고 금융산업의 대외경쟁력을 강화하기 위하여 1991년 8월 수립된 “4단계 금리자유화 추진계획”에 따라 1995년 11월 제3단계 금리자유화를 완결하였다. 이어 2004년 2월부터는 요구불예금 금리도 자유화함에 따라 모든 예금의 금리상한 규제가 폐지되었다. 우리나라의 경우 금융부문 낙후의 주요 원인이 금리의 가격기능 위축에 있다는 점에서 금리자유화는 시장원리에 의한 경제운용과 통화정책의 유효성 제고를 위한 기반이 되었다. ㄱ', related_words = '{}'::text[] WHERE id = 106;  -- 금리자유화
UPDATE public.words SET meaning = '산업자본과 금융자본이 결합하는 것을 제한하는 원칙을 금산분리라고 한다.', detailed_meaning = '산업자본과 금융자본이 결합하는 것을 제한하는 원칙을 금산분리라고 한다. 은행업 등 금융산업은 예금이나 채권 등을 통하여 조달된 자금을 재원으로 하여 영업활동을 해서 자기자본비율이 낮은 특징이 있다. 이 때문에 금융산업의 소유구조는 다른 산업에 비해 취약한 편이며 산업자본의 지배하에 놓일 수 있는 위험이 존재한다. 산업자본이 금융자본을 지배하게 되면, 은행이 특정 기업의 사금고처럼 이용될 수 있는 한편, 지배기업이 다른 경쟁 기업보다 유리한 조건으로 자금을 조달할 수 있어 시장의 공정한 경쟁을 저해하고 독과점을 초래할 수 있다. 이러한 이유로 은행법을 통해 산업자본이 보유할 수 있는 은행지분을 원칙적으로 4% 한도로 제한하고 있다.', related_words = '{}'::text[] WHERE id = 109;  -- 금산분리
UPDATE public.words SET meaning = '금융공황(Banking Panic)은 일부 금융기관이 실물경제 침체 등으로 인한 대출 부실화로 심각한 경영난에 빠졌을 때 예금인출사태(bank run)가 해당 금융기관만이 아닌 다른 금융기관에까지', detailed_meaning = '금융공황(Banking Panic)은 일부 금융기관이 실물경제 침체 등으로 인한 대출 부실화로 심각한 경영난에 빠졌을 때 예금인출사태(bank run)가 해당 금융기관만이 아닌 다른 금융기관에까지 급속하게 확산되어 금융시장 전체가 신용경색 사태에 직면하는 현상을 말한다. 이때 금융기관의 자산가치가 급격히 하락하면서 경기침체도 가속화된다. 금융공황은 증시 폭락, 금융자산 버블 붕괴, 통화위기, 국가부도 등을 동반하기도 한다. 예를 들어, 1907년 미국에서 발생한 금융공황을 보면, 뉴욕증권거래소 주가가 전년도 최고치에 비해 절반 수준까지 폭락하면서 다수의 은행에서 예금인출사태가 일어났다. 뉴욕에서 시작된 위기가 곧 미국 전역에 확산되면서 많은 은행과 기업이 파산하고 실업자 수는 400만명에 달하였다. 예금인출사태가 발생한 것은 뉴욕의 금융기관에 유동성이 부족했던 데다 예금자의 불신이 커졌던 데 기인한다. 당시 중앙은행이 존재하지 않았던 미국은 금융공황을 극복하기 위하여 1913년 12월 윌슨 대통령의 중앙은행 설립 관련 법안 서명을 거쳐 연방준비제도(Federal Reserve System)를 설립하였다.', related_words = ARRAY['뱅크런','연방준비제도(FRS)/연방준비은행(FRB)']::text[] WHERE id = 111;  -- 금융공황
UPDATE public.words SET meaning = '금융상황지수(FCI; Financial Conditions Index)는 전반적인 금융여건의 완화 또는 긴축 여부를 판단하기 위한 지수이다.', detailed_meaning = '금융상황지수(FCI; Financial Conditions Index)는 전반적인 금융여건의 완화 또는 긴축 여부를 판단하기 위한 지수이다. 금융상황은 통화정책의 1차 파급경로로서 실물경제전반에 영향을 미치는 만큼 주요국 중앙은행들은 금리, 환율, 주가, 신용스프레드, 주택가 격 등 다양한 금융변수를 이용하여 지수를 산출하고 이를 통화정책 운영에 참고하고 있다. 예를 들어, 장단기 시장금리가 낮아지고 주가가 상승하는 경우 금융상황이 완화된 것으로 해석된다. 반대로 금리 상승, 주가 하락 등이 나타나면 금융상황이 긴축된 것으로 본다. 한국은행은 단기금리, 실효환율, 주가, 기간스프레드, 리스크프리미엄, 주택가격의 6 개 변수의 장기추세 대비 격차를 가중합산한 후 표준화하여 FCI 지수를 산출해 왔으며, 2025년 3월부터는 금융여건이 일정 시차를 두고 성장에 영향을 미치는 점을 고려하여현재의 금융상황을 판단할 수 있도록 고안된 FCI-G(1년, 3년)를 신규로 산출하여 금융상황 평가에 활용하고 있다.', related_words = '{}'::text[] WHERE id = 114;  -- 금융상황지수(FCI)
UPDATE public.words SET meaning = '금융불안을 초래할 수 있는 시스템 리스크는 시계열 차원뿐만 아니라 특정 시점에서 종합적으로 파악할 필요가 있는데, 특정 시점에서 시스템 리스크를 초래할 수 있는 핵심 요인인 상호연계성은 해당', detailed_meaning = '금융불안을 초래할 수 있는 시스템 리스크는 시계열 차원뿐만 아니라 특정 시점에서 종합적으로 파악할 필요가 있는데, 특정 시점에서 시스템 리스크를 초래할 수 있는 핵심 요인인 상호연계성은 해당 금융업권(기관)이 영업활동 과정에서 여타 금융업권(기관)과 밀접하게 연결된 정도를 의미한다. 금융시스템 상호연계 구조는 금융기관 간 자금의 조달 및운용을 통한 실제 상호거래 또는 금융기관의 주가, 금리 등 금융시장 가격변수의 상관관계 등을 이용하여 분석한다.', related_words = ARRAY['시스템 리스크']::text[] WHERE id = 115;  -- 금융시스템 상호연계성
UPDATE public.words SET meaning = '기존 금융안정포럼(FSF)의 국제금융시장 안정 기능을 보다 강화하기 위하여 동 포럼의 참여 대상, 책무, 권한 등을 확대·개편하여 2009년 4월 금융안정위원회(FSB; Financial', detailed_meaning = '기존 금융안정포럼(FSF)의 국제금융시장 안정 기능을 보다 강화하기 위하여 동 포럼의 참여 대상, 책무, 권한 등을 확대·개편하여 2009년 4월 금융안정위원회(FSB; Financial Stability Board)가 설립되었다. 현재 25개국의 금융당국(중앙은행, 재무부 및 감독기관)과 10개 국제기구 대표가 회원으로 활동하고 있으며 우리나라에서는 한국은행과 금융위원회가 참여하고 있다. 최고의사결정기구는 총회(Plenary)로서 통상 1년에 두 번 개최되며, 총회를 효과적으로 보좌할 수 있도록 산하에 운영위원회를 설치·운영하고 있다. 아울러 FSB의 책무 수행을 지원하기 위하여 취약성평가 상임위(SCAV), 감독·규제협력상임위(SRC), 기준이행 상임위(SCSI), 예산·재원 상임위(SCBR) 등 4개의 상임위원회를 두고 있다.', related_words = '{}'::text[] WHERE id = 118;  -- 금융안정위원회(FSB)
UPDATE public.words SET meaning = '금융연관비율(Financial Interrelations Ratio)은 한 나라의 금융자산 잔액을 유형자산(실물자산 또는 국부 = 유형자산 + 순 대외자산) 잔액으로 나눈 비율로 골드스미스', detailed_meaning = '금융연관비율(Financial Interrelations Ratio)은 한 나라의 금융자산 잔액을 유형자산(실물자산 또는 국부 = 유형자산 + 순 대외자산) 잔액으로 나눈 비율로 골드스미스 (R.W.Goldsmith)가 사용하기 시작하였다. 이는 실물 면의 자본축적 잔액에 대한 금융 면의 금융자산 잔액의 비율로서 유형고정자산의 증대를 위한 금융조직의 발달 정도, 즉 금융구조의 고도화 또는 금융자산축적의 정도를 나타내는 지표라 할 수 있다. 그러나 한 나 라의 유형자산 규모를 파악하는 것이 쉽지 않아 유형자산 대신 명목 GNI를 이용하기도 한다. 일반적으로 금융연관비율은 경제의 발전에 따라 증대되는 경향이 있다.', related_words = '{}'::text[] WHERE id = 119;  -- 금융연관비율(골드스미스비율)
UPDATE public.words SET meaning = '분산원장 등 신기술의 출현과 핀테크의 발달에 따라 금융업의 분화 현상이 심화됨으로써금융서비스가 더 이상 기존 금융시스템과 중개기관에 의존하지 않고 다양한 형태로 분절되는', detailed_meaning = '분산원장 등 신기술의 출현과 핀테크의 발달에 따라 금융업의 분화 현상이 심화됨으로써금융서비스가 더 이상 기존 금융시스템과 중개기관에 의존하지 않고 다양한 형태로 분절되는 탈중개화(disintermediation) 및 탈집중화(decentralization)되는 경향이 나타나고 있다. 여기서 금융의 탈중개화는 블록체인을 통한 송금, P2P대출처럼 금융중개기관을 거치지 않고 거래가 당사자 간에 직접 이뤄지는 현상을 말한다. 이는 금융중개기관에 대한 수요를 감소시키는 반면, 금융서비스 공급자의 수를 증가시키는 방향으로 작용한다.', related_words = ARRAY['핀테크','금융의 탈집중화','블록체인','P2P대출']::text[] WHERE id = 121;  -- 금융의 탈중개화
UPDATE public.words SET meaning = '금융의 탈집중화(Decentralization)는 탈중개화와 유사한 개념으로 분야별 금융시장에 새로 진입한 핀테크 업체들의 파괴적인 경쟁력 때문에 금융 분야별로 서비스가 더', detailed_meaning = '금융의 탈집중화(Decentralization)는 탈중개화와 유사한 개념으로 분야별 금융시장에 새로 진입한 핀테크 업체들의 파괴적인 경쟁력 때문에 금융 분야별로 서비스가 더 세분화되는(unbundling) 현상을 말한다. 예를 들면, 대출 분야의 경우 지점을 갖지 않는 인터넷전문은행이 인터넷(모바일) 금융서비스 분야에 새로 진입하여 획기적으로 단기간에 대규모 고객을 확보함에 따라, 기존 대형 은행들의 고객 이탈을 초래하고, 해외송금 분야에서는 블록체인·모바일네트워크 등을 활용해서 금융중개기관을 거치지 않고 더 싼 수수료로 직접 수신자에게 송금하는 핀테크 업체가 등장하였다. ‘금융의 탈중개화’(disintermediation)는 블록체인을 통한 송금, P2P대출처럼 금융중개를 거치지 않고 거래가 당사자 간에 직접 이뤄진다는 면에서 탈중개화와 다소 다르다.', related_words = ARRAY['핀테크','P2P대출','블록체인']::text[] WHERE id = 122;  -- 금융의 탈집중화
UPDATE public.words SET meaning = '금융이해력은 재무적 자원을 효과적으로 관리하고 생애 전반에 걸쳐 재정적 안정을 확보하기 위해 필요한 금융 지식, 기술, 태도 등을 포괄하는 능력을 의미한다.', detailed_meaning = '금융이해력은 재무적 자원을 효과적으로 관리하고 생애 전반에 걸쳐 재정적 안정을 확보하기 위해 필요한 금융 지식, 기술, 태도 등을 포괄하는 능력을 의미한다. 이는 금융 정보를 이해하고 활용하여 합리적인 금융 결정을 내리고, 자신의 재무 목표를 달성하는 데 필요한 역량을 말한다. 일반적으로 금융이해력은 금융지식, 금융행위, 금융태도와 같은 요 소들을 포괄한다. 금융 지식은 금융 상품, 시장, 서비스 등에 대한 기본적인 이해력을 말한다. 금융 행위는 예산 관리, 저축, 투자, 신용 관리 등 실제 금융 활동을 효과적으로 수행하는 능력을 말한다. 금융 태도는 미래를 위한 계획, 위험 감수, 소비 습관 등 금융 의사결정에 영향을 미치는 태도를 의미한다. 이러한 금융이해력은 개인의 재정적 안정뿐만 아니라 사회 전체의 경제적 복지에도 영향을 미치기 때문에 금융교육을 통해 금융이해력을 높이는 것이 매우 중요하다. 이와 관련해 한국은행과 금융감독원은 2012년부터 OECD INFE(International Network on Financial Education) 가이드 라인을 바탕으로 한 ‘전국민 금융이해력 조사’를 공동 실시하고 있다. ㄱ', related_words = ARRAY['금융 지식','금융 행위','금융 태도','디지털 금융이해력']::text[] WHERE id = 123;  -- 금융이해력
UPDATE public.words SET meaning = '금융채는 은행, 금융투자회사, 리스회사, 신용카드회사 등 금융기관이 장기적으로 안정적인 자금을 조달하기 위하여 발행하는 채권을 말한다.', detailed_meaning = '금융채는 은행, 금융투자회사, 리스회사, 신용카드회사 등 금융기관이 장기적으로 안정적인 자금을 조달하기 위하여 발행하는 채권을 말한다. 예를 들면, 은행채는 「은행법」에 근거하여 은행이 자기자본의 5배 이내에서 발행할 수 있으며, 산업금융채권의 경우 「한국산업은행법」에 근거하여 한국산업은행이 자본금 및 적립금의 30배 이내에서 발행할 수있다. 중소기업금융채권은 기업은행이 「중소기업은행법」에 근거하여 자본금 및 적립금의 20배 이내에서 발행할 수 있다. 금융채는 채권의 성격에 따라 일반채권, 후순위채권, 하이 브리드채권(신종자본증권), 기타 주식관련 사채, 옵션부채권 등으로 구분된다. 금융기관 ㄱ은 금융채를 발행하여 조달한 자금을 주로 장기 산업자금으로 대출한다. 한편 금융채 금리는 은행의 대출금리와도 관련이 있다. 금융채 금리는 단독으로 은행 대출금리의 준거금리가 되기도 하고 자금조달비용지수(COFIX; Cost of Funds Index) 산정시 예금금리, CD금리 등과 함께 가중평균되어 반영되기도 한다.', related_words = ARRAY['자금조달비용지수(COFIX)']::text[] WHERE id = 127;  -- 금융채
UPDATE public.words SET meaning = '금전신탁이란 수탁자가 금전을 신탁재산으로 위탁받아 이를 대출, 채권 등 적절한 투자대상에 운용하여 얻은 이익을 수익자에게 금전 등의 형태로 되돌려 주는 제도이다.', detailed_meaning = '금전신탁이란 수탁자가 금전을 신탁재산으로 위탁받아 이를 대출, 채권 등 적절한 투자대상에 운용하여 얻은 이익을 수익자에게 금전 등의 형태로 되돌려 주는 제도이다. 신탁은 재산(금전, 부동산 등)을 잘 운용하기 어려운 사람들을 위해 전문가에게 재산을 맡겨 잘운용하여 경제적 이득을 얻는 데 그 의의가 있다. 금전신탁은 수익자가 신탁재산의 운용을 지정하느냐 여부에 따라 특정금전신탁(지정)과 불특정금전신탁(비지정)으로 구분되며, 불특정금전신탁에는 단위 금전신탁, 추가 금전신탁, 가계 금전신탁, 기업 금전신탁 등이 있다. 한편, 은행에서 취급하고 있는 금전신탁과 예금과의 차이점을 살펴보면 운용방법에 서는 금전신탁은 신탁법 및 신탁계약에서 정해진 것에 국한된 반면 예금은 은행법 등에서 정한 범위 내에서 자유롭게 운용할 수 있다. 이익분배에 있어서는 금전신탁은 실적배당, 예금은 확정이율을 원칙으로 한다.', related_words = '{}'::text[] WHERE id = 130;  -- 금전신탁
UPDATE public.words SET meaning = '기념화폐는 국가적 행사, 역사적 사건, 중요한 인물 또는 국가유산 등을 기념하기 위해 특 ㄱ별히 발행되는 화폐로서 유통 목적으로 발행되는 통용 화폐와 달리, 주로 수집 가치와 기념적 의미를 지니며', detailed_meaning = '기념화폐는 국가적 행사, 역사적 사건, 중요한 인물 또는 국가유산 등을 기념하기 위해 특 ㄱ별히 발행되는 화폐로서 유통 목적으로 발행되는 통용 화폐와 달리, 주로 수집 가치와 기념적 의미를 지니며 액면가보다 높은 가격에 판매되는 경우가 많다.우리나라에서는 기념화폐가 주화로 발행되는 경우 ‘기념주화’, 지폐로 발행되는 경우 ‘기념은행권’이라 한다. 한국은행은 1971년 우리나라 최초의 기념주화인 ‘대한민국 반만년역사’를 시작으로, 서울올림픽대회, 정부수립 50주년, 서울 G20 정상회의 개최 등 국가적행사와 전통민속놀이, 한국의 문화유산, 한국의 국립공원 등 다양한 주제를 담은 기념주화를 발행해 왔다. 한편, 기념은행권은 평창동계올림픽 개최 기념으로 최초의 액면 2000 원 기념은행권이 발행된 바 있다.', related_words = ARRAY['화폐 발행','화폐의 액면체계']::text[] WHERE id = 131;  -- 기념화폐
UPDATE public.words SET meaning = '국제결제은행(BIS)의 기준에 따른 은행의 자기자본(=기본자본+보완자본)을 구성하는 요 소로서, 예상외 손실(unexpected loss)이 발생할 경우 은행이 영업을 계속하면서 손실을 흡수할 수', detailed_meaning = '국제결제은행(BIS)의 기준에 따른 은행의 자기자본(=기본자본+보완자본)을 구성하는 요 소로서, 예상외 손실(unexpected loss)이 발생할 경우 은행이 영업을 계속하면서 손실을 흡수할 수 있는 자본(going-concern capital)을 의미하며, 보통주자본(CET1; Common Equity Tier 1)과 기타기본자본(AT1; Additional Tier 1)으로 구성된다. 2008년 금융위기를 계기로 실질적인 손실흡수능력이 강조되면서 바젤Ⅲ 규제에서는 보통주자본이 기본자본의 지배적인 비중을 차지하도록 하였으며 기타기본자본의 요건 및 공제항목의 적용을 강화하였다. 바젤 Ⅲ에서는 기본자본비율이 위험가중자산의 6.0% 이상이 되도록 규정하고 있다.', related_words = ARRAY['BIS 자기자본비율','보통주자본','기타기본자본','보완자본(Tier 2)']::text[] WHERE id = 133;  -- 기본자본(Tier 1)
UPDATE public.words SET meaning = '기업간(B2B) 지급시스템은 전자외상매출채권(전자채권)의 발행과 만기시 결제를 처리하는 시스템으로 2002년 3월 가동되었다.', detailed_meaning = '기업간(B2B) 지급시스템은 전자외상매출채권(전자채권)의 발행과 만기시 결제를 처리하는 시스템으로 2002년 3월 가동되었다. B2B 지급시스템으로 이용할 수 있는 서비스는 기업간 상거래로 발생한 채무를 기반으로 구매기업이 거래은행(발행은행)을 통하여 전자채권을 발행하고, 전자채권의 만기일에 판매기업이 거래은행(전자채권 보관은행)으로부터 구매기업이 결제한 전자채권대금을 회수하는 서비스이다. 채권의 만기일은 발행일로 부터 3영업일 이후부터 180일 이내이다. B2B 지급시스템의 이용 가능시간은 기본적으로 영업일 08시부터 22시까지이며, 전자채권 발행 및 취급과 관련한 수수료는 각 은행이 자율적으로 정한다.', related_words = '{}'::text[] WHERE id = 134;  -- 기업간(B2B) 지급시스템
UPDATE public.words SET meaning = '기업심리지수(CBSI; Composite Business Sentiment Index)는 기업경기실사지수(BSI)의 주요 지수를 이용하여 산출한 지표이다.', detailed_meaning = '기업심리지수(CBSI; Composite Business Sentiment Index)는 기업경기실사지수(BSI)의 주요 지수를 이용하여 산출한 지표이다. 제조업의 경우 업황, 생산, 신규수주, 제품재고, 자금사정의 BSI 수치를 합성하여 작성하며, 비제조업의 경우는 업황, 매출, 채산성, 자금사정의 BSI 수치를 합성하여 작성한다. CBSI는 100보다 클 경우 경제상황에 대한 기업들의 기대심리가 과거 평균보다 낙관적임을 나타내며, 반대로 100보다 작을 경우에는 비관적임을 의미한다.', related_words = ARRAY['기업경기실사지수(BSI)']::text[] WHERE id = 138;  -- 기업심리지수(CBSI)
UPDATE public.words SET meaning = '기초가격(Basic Price)은 일정 기간 동안 경제주체가 생산한 생산물을 가격으로 평가함에 있어 생산자가격에서 부가가치세와 같은 생산물세(production tax)를 제외하고 정부에 서 주는', detailed_meaning = '기초가격(Basic Price)은 일정 기간 동안 경제주체가 생산한 생산물을 가격으로 평가함에 있어 생산자가격에서 부가가치세와 같은 생산물세(production tax)를 제외하고 정부에 서 주는 보조금(subsidy)을 더한 가격을 의미하는 것으로 순수하게 생산자(주로 기업)가 갖게 되는 몫을 말한다. 일반적으로 생산물을 최종 소비하는 소비자가 지불하는 가격 즉, 구매자가격에는 생산물세와 보조금, 운수비용, 거래마진 등이 모두 포함되어 있으며, 생산자가격은 기초가격에다 생산물세를 더하고 보조금을 차감한 가격을 말한다. 예를 들어정부가 국민 건강증진의 일환으로 축산농가를 지원하기 위해 우유 1병에 50원의 보조금을 주며 100원의 생산물세와 200원의 거래마진이 발생한다고 가정하자. 또한 이 우유가 상점에서 1,000원에 판매되고 있다고 하자. 이 경우 구매자가격은 소비자가 지불하는 가 격 1,000원이며, 생산자가격은 구매자가격 1,000원에서 유통업자의 몫인 거래마진 200 원을 뺀 800원이고, 기초가격은 생산자가격 800원에서 정부에 납부하는 세금 100원을 차감하고 정부로부터 받은 보조금 50원을 더한 750원이 된다. GDP를 추계할 때 생산물의 가격평가는 기초가격으로 하는 것을 원칙으로 하는데, 그 이유는 생산성 분석 등에 세금 등으로 인해 초래되는 분석결과의 왜곡을 피하기 위해서다.', related_words = ARRAY['국내총생산(GDP)']::text[] WHERE id = 145;  -- 기초가격
UPDATE public.words SET meaning = '기축통화란 여러 국가의 암묵적인 동의하에 국제거래에서 중심적인 역할을 하는 통화를 지칭한다.', detailed_meaning = '기축통화란 여러 국가의 암묵적인 동의하에 국제거래에서 중심적인 역할을 하는 통화를 지칭한다. 구체적으로는 ① 국제무역결제에 사용되는 통화 ② 환율 평가 시의 지표가 되는 통화 ③ 대외준비자산으로 보유되는 통화 등의 의미를 포함한다. 그러므로 어떤 나라의 통화가 기축통화가 되기 위해서는 세계적으로 원활히 유통될 수 있도록 유동성이 풍부하여야 하고, 거래당사자들이 믿고 사용할 수 있도록 신뢰성을 갖추어야 하며, 국제적으로 경제력은 물론 정치력·군사력까지 인정받는 국가의 통화여야 한다. 20세기 초반까지는 세계 금융경제의 중심이었던 영국의 파운드화가 기축통화로서 국제거래에 주로 이 용되었으며, 2차 세계대전 이후에는 전 세계 외환거래 및 외환보유액의 상당 부분을 차지하는 미국 달러화가 기축통화로 인정받고 있다. 한편 현재 국제거래에서 비교적 자주사용되는 통화로는 미국 달러화 이외에도 유로화, 영국 파운드화, 일본 엔화, 스위스 프랑화 등이 있는데 이들을 흔히 교환성 통화라 한다.', related_words = ARRAY['교환성 통화']::text[] WHERE id = 146;  -- 기축통화
UPDATE public.words SET meaning = '기타기본자본(AT1; Additional Tier 1)은 바젤Ⅲ 자본규제에서 기본자본(Tier 1)을 구성하는 요소로서, 은행의 계속적인 영업을 전제로 손실흡수능력이 있다고 인정되는(혹은 은 행의', detailed_meaning = '기타기본자본(AT1; Additional Tier 1)은 바젤Ⅲ 자본규제에서 기본자본(Tier 1)을 구성하는 요소로서, 은행의 계속적인 영업을 전제로 손실흡수능력이 있다고 인정되는(혹은 은 행의 손실을 보통주자본 다음의 순서로 보전할 수 있는) 자본을 의미하며 영구적 성격을 지닌 자본증권의 발행으로 인한 자본금·자본잉여금 등이다. 기타기본자본증권으로 인정받기 위해서는 예금자, 일반 채권자 및 후순위채권보다 후순위일 것, 영구적일 것, 배당및 이자지급의 임의성, 중도상환 유인이 없을 것 등의 요건을 충족해야 한다(참고 「은행업감독업무시행세칙」별표 3).', related_words = ARRAY['기본자본(Tier 1)','보통주자본(CET1)']::text[] WHERE id = 147;  -- 기타기본자본(Additional Tier 1)
UPDATE public.words SET meaning = '긴급수입제한조치(Safeguard) 즉, 세이프가드란 특정 품목의 수입이 급증하여 국내 업체에 심각한 피해가 발생하거나 그럴 우려가 있을 경우, 수입국이 관세 인상이나 수입량 제한 등을 통해', detailed_meaning = '긴급수입제한조치(Safeguard) 즉, 세이프가드란 특정 품목의 수입이 급증하여 국내 업체에 심각한 피해가 발생하거나 그럴 우려가 있을 경우, 수입국이 관세 인상이나 수입량 제한 등을 통해 수입품에 대한 규제를 할 수 있는 제도이며 무역장벽의 하나라고 볼 수 있다. 현재 세계무역기구(WTO; World Trade Organization)는 가입국들이 긴급수입제한 조치를 실행할 권리를 인정하고 있다. 수입물품에 대한 수량제한, 관세율 조정 및 국내산업의 구조조정을 촉진하기 위한 지원정책 등이 세이프가드로 동원될 수 있다. 그러나 세계무역기구의 세이프가드 협정은 제한적으로 취해져야 하고 세이프가드를 실시하는 수입 ㄱ국은 해당 물품의 수출국에 적절한 보상을 해줄 것을 권고하고 있다.', related_words = ARRAY['상계관세','슈퍼301조']::text[] WHERE id = 151;  -- 긴급수입제한조치
UPDATE public.words SET meaning = '경기과열 우려가 있는 경우 재정 또는 통화정책으로 가계, 기업, 정부 등 각 경제주체들의 재화 및 서비스에 대한 수요, 투자 의지를 위축시켜 지출을 줄이는 등 경기의 과열을 방지하려는 정책을', detailed_meaning = '경기과열 우려가 있는 경우 재정 또는 통화정책으로 가계, 기업, 정부 등 각 경제주체들의 재화 및 서비스에 대한 수요, 투자 의지를 위축시켜 지출을 줄이는 등 경기의 과열을 방지하려는 정책을 긴축정책(Contractionary Policy)이라고 한다. 경기가 과열되어 물가급등 에 대한 염려가 커지면 정부나 지방자치단체는 예산을 편성·실행함에 있어서 지출을 삭감·억제함과 동시에 공채의 정리 및 신규 모집을 하지 않는 정책을 취한다. 세입 일부를 다음 연도로 이월하거나 공정이율의 인상을 중심으로 하는 금융긴축 조치 등도 시행된다. 한편 중앙은행은 물가급등에 대한 우려가 커지면 시중에 유통되는 통화량을 줄이거나 금리를 인상한다. 이렇게 되면 경제주체들의 지출이 줄어들면서 국민소득이 감소하고 지출축소와 소득 감소의 연쇄 과정이 발생하면서 물가도 하락하게 된다.', related_words = ARRAY['경기조절정책/경제안정화정책','재정정책','통화정책']::text[] WHERE id = 152;  -- 긴축정책
UPDATE public.words SET meaning = '정부가 경제정책으로 대기업과 고소득층 또는 부유층의 소득과 부를 먼저 늘려주게 되면이들의 소비와 투자 증가를 통해 전체 경제활동이 활발해지면서 결국에는 중소기업과 저소득층도 혜택을 볼 수 있다는', detailed_meaning = '정부가 경제정책으로 대기업과 고소득층 또는 부유층의 소득과 부를 먼저 늘려주게 되면이들의 소비와 투자 증가를 통해 전체 경제활동이 활발해지면서 결국에는 중소기업과 저소득층도 혜택을 볼 수 있다는 주장이다. 이러한 주장은 분배와 형평성보다는 성장과 효율성을 중시하는 논리에 근거한다. 실제로 미국에서는 제41대 대통령인 부시가 1989년부터 1992년까지 낙수효과(Trickle-Down Effect)에 기반을 둔 경제정책을 채택하기도 했다. 그러나 1993년 1월 당선된 클린턴 행정부는 이를 뒷받침하는 근거가 없다는 이유를 들어 이전의 정책을 포기한 바 있다. 2015년 국제통화기금(IMF)은 선진국, 신흥국 및개발도상국을 대상으로 한 연구(“Causes and Consequences of Income Inequality: A Global Perspective”, IMF 2015년 6월)를 통해 상위소득 20% 계층의 비중이 커질수록경제성장률이 낮아진다는 실증분석 결과를 발표하였는데, 이는 낙수효과가 현실에서 작동하지 않을 수 있음을 시사한다.', related_words = ARRAY['분수효과']::text[] WHERE id = 154;  -- 낙수효과
UPDATE public.words SET meaning = '납부자자동이체(Standing Order)는 은행지로 업무의 한 형태로 고객이 거래은행이 아닌 다른 은행에 대출원리금, 정기적금 등을 정기적으로 납부할 때 거래은행의 본인계좌에서 다른 은행으로', detailed_meaning = '납부자자동이체(Standing Order)는 은행지로 업무의 한 형태로 고객이 거래은행이 아닌 다른 은행에 대출원리금, 정기적금 등을 정기적으로 납부할 때 거래은행의 본인계좌에서 다른 은행으로 자동 이체시켜 주는 업무로서 1994년 4월부터 실시되었다. 납부자자동이 체는 주로 대출원리금, 적금 납입금, 신탁적립금, 기타 정기납부금(각종회비, 기부금, 임 차료) 등 정기적인 은행납입금 납부시 이용되고 있다.', related_words = ARRAY['지로(GIRO)','출금이체']::text[] WHERE id = 157;  -- 납부자자동이체
UPDATE public.words SET meaning = '바젤 자본규제에서 정하고 있는 최소 요건(신용평가 시스템의 신뢰도 확보를 위해 갖추어야 할 최소한의 양적·질적 요건)을 충족하여 감독당국의 승인을 받은 은행이 자산군별로 리스크 측정 요소(부도율,', detailed_meaning = '바젤 자본규제에서 정하고 있는 최소 요건(신용평가 시스템의 신뢰도 확보를 위해 갖추어야 할 최소한의 양적·질적 요건)을 충족하여 감독당국의 승인을 받은 은행이 자산군별로 리스크 측정 요소(부도율, 부도시 손실률, 부도시 익스포저 등)를 자체 측정모형을 통해 추정하고 이를 바젤위원회(BCBS)가 정한 내부등급법 산식에 대입하여 신용리스크에 대한 위험가중자산을 산출하는 방법을 말한다. 내부등급법은 부도율에 대해서만 자체추정을 허용하고 나머지 요소들은 감독당국이 정한 값을 사용하도록 하는 기본내부등급법과 모든 리스크 측정 요소의 자체 추정을 허용하는 고급내부등급법으로 구분된다. 내부등급법은 바젤Ⅱ부터 자본규제 체계의 리스크 민감도를 높이고 은행의 리스크 관리기법개선을 촉진할 목적으로 도입되었다. 그러나 리스크 측정모형과 관련된 불확실성으로 인해 위험가중자산이 잘못 산출될 가능성(모형 리스크)이 존재하는 데다 내부모형의 차이로 인해 은행간·국가간 위험가중자산의 편차가 과도하게 확대되어 자기자본비율 규제의 신뢰성을 저하시키는 요인이 되었다. 이에 따라 바젤Ⅲ에서는 객관적 리스크 측정이 어렵거나 자료가 부족하여 은행 자체 모형의 검증이 어려운 자산군에 대해서는 내부등급법 사용을 제한하는 등 위험가중자산의 편차를 축소하기 위한 조치를 취하였다.', related_words = '{}'::text[] WHERE id = 159;  -- 내부등급법
